lFrom = from.ANTHROPIC_BASE_URL ?? (baseUrl ? \"environment\" : keyFrom);\n    const split =\n      urlFrom === keyFrom\n        ? undefined\n        : serverText(\"keyRefusedSplit\", {\n            address: serverText(settingsScopeText(urlFrom)),\n            key: serverText(settingsScopeText(keyFrom)),\n          });\n    return split === undefined ? { host } : { host, split };\n  }\n\n  /** The routing variables as the last listing or settings change saw them (`routeSignature`),\n   *  so a write to settings.json that left them alone is not taken for a change. */\n  private routeSeen: string | undefined;\n\n  /** Where `routeSeen` is kept across restarts, beside the lineup it vouches for. */\n  private routeSeenPath() {\n    return join(this.stateDir, \"route-seen.json\");\n  }\n\n  /**\n   * The first look at the routing variables this boot. The lineup on disk was answered under\n   * whatever they were when it was written; a router switched while dsh was down leaves it\n   * naming the wrong models until some session's process answers again, which without this is\n   * the first turn. So the signature is kept on disk with the lineup, and a boot that finds\n   * another one asks the CLI again before the picker is trusted. A box that has no kept\n   * signature yet asks once, unless its lineup was answered this boot. Failures are swallowed:\n   * the listing goes on with what it has.\n   */\n  private async routeFirstSeen(signature: string) {\n    this.routeSeen = signature;\n    const kept = await readFile(this.routeSeenPath(), \"utf8\").catch(() => \"\");\n    // A settings change landed during the read and has written its own, newer signature.\n    if (this.routeSeen !== signature) return;\n    if (kept === signature) return;\n    await this.keepRouteSeen(signature);\n    // A lineup asked for this boot (the boot probe, a session's process) was asked under these\n    // variables already, whether or not it answered; only one read back from disk can be from\n    // before the change.\n    if (this.cliModelsAt !== 0 || this.lineupProbe !== undefined) return;\n    await this.relistCliModels();\n    await this.routeChanged();\n  }\n\n  /** Write the signature the lineup now on disk was answered under. */\n  private async keepRouteSeen(signature: string) {\n    try {\n      await mkdir(this.stateDir, { recursive: true });\n      await writeFile(this.routeSeenPath(), signature);\n    } catch {\n      /* read-only state dir: the next boot asks the lineup again, which is the safe side */\n    }\n  }\n\n  /**\n   * Where this mount's traffic goes right now. Never waits on the endpoint: it answers from what\n   * is kept and, when that is missing or old, asks behind the caller and lists again if the\n   * answer moved (`routeChanged`). Also arms the watch on the settings files, here rather than\n   * in the constructor because dsh builds adapters it never lists from.\n   */\n  async route(): Promise<Route> {\n    // An ssh box answers for itself (`box-route.ts`), and is `unknown` until it has: its files\n    // cannot be watched from here, so its answer is asked again as it ages instead.\n    if (this.config.sshHost) {\n      const box = boxRouteKnown(this.config.sshHost, () => void this.routeChanged());\n      return box ? boxRouteState(box) : { state: \"unknown\" };\n    }\n    const env = routeEnvIn(await this.claudeEnv());\n    if (this.routeSeen === undefined) void this.routeFirstSeen(routeSignature(env)).catch(() => {});\n    // The real home: with the mirror on, `claudeHome` holds links, and a link's target\n    // changing is not an event in the directory that holds the link.\n    for (const dir of [this.realClaudeHome, managedDir()])\n      watchSettingsIn(dir, this.providerId, () => void this.settingsMoved());\n    const hints = await readHints(join(STATE_DIR, \"hints.json\"));\n    return routeOf(env, { forwards: firstPartyMode(hints) === \"on\" }, (baseUrl) =>\n      firstPartyKnown(baseUrl, () => void this.routeChanged()),\n    );\n  }\n\n  /**\n   * The name of `model` when only a router can answer for it and this mount is talking to\n   * Anthropic, else undefined. A session can sit on such a model after the router is switched\n   * off (dsh refuses a new pick of an unlisted model, not a prompt on one already picked), and so\n   * can a new session, which opens on the last model picked. Its turn fails with the API's\n   * \"issue with the selected model\", and this is what lets the failure say why (`finishReason`).\n   */\n  private async routerOnly(model: string | undefined): Promise<string | undefined> {\n    if (!model || (await this.route()).state !== \"direct\") return undefined;\n    const picker = await this.pickerSettings();\n    const row = (await catalogNow(this.cliModels, picker)).find((m) => m.id === model);\n    if (!row) return undefined;\n    const direct = await catalogNow(this.cliModels, picker, { state: \"direct\", claudeToo: false });\n    return direct.some((m) => m.id === model) ? undefined : row.name;\n  }\n\n  /**\n   * The window a session on `model` in `cwd` has to be started with, or undefined when the CLI's\n   * own figure stands: every model of Claude's, and every row whose entry states no size. Set\n   * for a router's alias (the size kept in Settings, or the default) and for an added model with\n   * a stated size. A window someone chose themselves outranks it and leaves this undefined:\n   * `autoCompactWindow` in a settings file, or either of the CLI's two variables already in the\n   * environment or a settings `env`; the CLI lets the variable beat the settings key, so setting\n   * it here would overrule that choice.\n   */\n  private async sizedWindow(model: string | undefined, cwd: string): Promise<number | undefined> {\n    if (!model) return undefined;\n    const settings = await this.settingsEnv(cwd);\n    const env = { ...process.env, ...settings.env };\n    if (\n      settings.autoCompactWindow !== undefined ||\n      env.CLAUDE_CODE_AUTO_COMPACT_WINDOW !== undefined ||\n      env.CLAUDE_CODE_MAX_CONTEXT_TOKENS !== undefined\n    )\n      return undefined;\n    return this.rowWindow(model);\n  }\n\n  /** The window this mount's row for `model` states, when it is one the plugin sized (a\n   *  router's alias, an added model with a size), else undefined. The allowlist and the \"replace\n   *  the built-in rows\" switch are left out: a session on a model they hide still has its row. */\n  private async rowWindow(model: string | undefined): Promise<number | undefined> {\n    if (!model) return undefined;\n    const picker = await this.pickerSettings();\n    const rows = picker && { ...picker, availableModels: undefined, replaceBuiltInOptions: false };\n    const row = (await catalogNow(this.cliModels, rows)).find((m) => m.id === model);\n    return row?.sized ? row.contextWindow : undefined;\n  }\n\n  /** What a listing is filtered by: the state, and this mount's \"also list Claude's own models\"\n   *  switch (`routedClaude:<provider>` in the hints store). */\n  private async routeFilter(): Promise<RouteFilter> {\n    const hints = await readHints(join(STATE_DIR, \"hints.json\"));\n    return {\n      state: (await this.route()).state,\n      claudeToo: hints[`routedClaude:${this.providerId}`] === true,\n    };\n  }\n\n  /**\n   * A settings file was written. When the routing variables really moved (a router switched on\n   * or off, a provider changed), the CLI's lineup is asked for again before anything is told:\n   * the rows it names are the router's only once the lineup says so, and the kept one is from\n   * before the change. A write that left those variables alone ends here, which is most of them.\n   */\n  private async settingsMoved() {\n    const signature = routeSignature(routeEnvIn(await this.claudeEnv()));\n    if (signature === this.routeSeen) return;\n    this.routeSeen = signature;\n    await this.keepRouteSeen(signature);\n    await this.relistCliModels();\n    await this.routeChanged();\n  }\n\n  /** Tell dsh's pickers and the plugin's own views that this box's lists moved: the event dsh\n   *  reloads `listModels` on, and the hints event the Settings rows built on these lists re-read\n   *  on (the same one a saved custom model sends). */\n  private async routeChanged() {\n    this.modelsUpdated();\n    const data = await readHints(join(STATE_DIR, \"hints.json\")).catch(() => ({}));\n    hub.publish({ kind: \"hints\", session: null, data });\n  }\n\n  /** settings.json's say over the picker, plus this mount's `customModels`. The file is read on\n   *  every listing rather than cached: an edit to settings.json takes effect at once. */\n  private async pickerSettings() {\n    const fromFile = await readPickerSettings(join(this.claudeHome, \"settings.json\"));\n    // The alias names from every layer of the mount's env: they work exported in the shell dsh\n    // started from and in the managed file as well as in settings.json. An ssh box's are its\n    // own, as it last answered, and the ones in this box's file name this box's router.\n    const far = this.config.sshHost\n      ? boxRouteKnown(this.config.sshHost, () => void this.routeChanged())\n      : undefined;\n    if (this.config.sshHost && fromFile) delete fromFile.aliasNames;\n    const { aliasNames, aliasModels } = this.config.sshHost\n      ? (far?.env ?? { aliasNames: {}, aliasModels: {} })\n      : routeEnvIn(await this.claudeEnv());\n    const named =\n      Object.keys(aliasNames).length + Object.keys(aliasModels).length === 0\n        ? fromFile\n        : {\n            ...(fromFile ?? { options: [], replaceBuiltInOptions: false }),\n            aliasNames,\n            aliasModels,\n          };\n    // The sizes set in Settings for the aliases the router took over. Not on a mount that talks\n    // straight to Anthropic: an alias renamed there still reaches the Claude model the CLI\n    // knows, and capping it at the default would shrink a real 1M window.\n    if (named?.aliasNames && (await this.route()).state !== \"direct\")\n      named.routerWindows = hintRouterWindows(\n        await readHints(join(STATE_DIR, \"hints.json\")),\n        this.providerId,\n      );\n    return withCustomModels(named, [\n      ...this.config.customModels,\n      ...(await this.savedCustomModels()),\n    ]);\n  }\n\n  /** The models someone added for this mount in Settings; one small file read per listing, like\n   *  the hide switches, so a row added in one browser is in every picker at its next listing. */\n  async savedCustomModels(): Promise<CustomModel[]> {\n    return (await loadCustomModels(STATE_DIR))[this.providerId] ?? [];\n  }\n\n  /**\n   * Replace the Settings list of added models for the mount `provider` names, then tell dsh the\n   * picker changed. The answer is the list as stored, or `error` with the sentence to show (an id\n   * the CLI could not take, a duplicate, no such mount), in which case nothing was written.\n   */\n  async setCustomModels(\n    provider: string,\n    models: readonly CustomModel[],\n  ): Promise<{ models: CustomModel[] } | { error: string }> {\n    const mount = [...ClaudeCodeAdapter.mounts(this)].find((m) => m.providerId === provider);\n    if (!mount) return { error: serverText(\"customModelBox\", { provider }) };\n    const rows = checkCustomModels(models);\n    if (!Array.isArray(rows)) return { error: rows };\n    await saveCustomModels(STATE_DIR, provider, rows);\n    this.modelsUpdated();\n    return { models: rows };\n  }\n\n  /** A box without a login lists nothing: dsh's catalog drops a provider whose listing throws into\n   *  its \"could not load\" row with a Retry, which is the honest picker for a box no turn can use.\n   *  The row names the fix; Retry after the login brings the models back. */\n  override async listModels(provider: string) {\n    // A box named logged out asks its CLI again before refusing: a login made in a terminal there\n    // would otherwise stay hidden until Settings was opened or dsh restarted, and the picker's\n    // Retry would keep answering from a stale flag. One `claude auth status` per open while out.\n    if (this.loggedOut) {\n      forgetIdentity();\n      const who = await accountIdentity(\n        this.config.command,\n        this.claudeHome,\n        this.config.sshHost,\n      ).catch(() => ({ loggedIn: false }));\n      if (who.loggedIn) this.setLoggedIn(true);\n    }\n    if (this.loggedOut)\n      throw new Error(serverText(\"loggedOutError\", { host: this.config.sshHost || hostname() }));\n    await this.cliSeed;\n    await this.probeCliModels();\n    const models = await getCatalog(\n      undefined,\n      this.cliModels,\n      await this.pickerSettings(),\n      await this.routeFilter(),\n    );\n    return withoutHiddenModels(models, await this.hiddenModelIds()).map((m) =>\n      modelInfo(provider, m),\n    );\n  }\n\n  /**\n   * Every id this mount's picker leaves out: the plugin config's `hiddenModels`, then the Settings\n   * switches for this mount, which live in the hints store (one file for every mount, keyed by\n   * provider id, so each box has its own list and every browser sees the same one). One small\n   * file read per listing.\n   */\n  async hiddenModelIds(): Promise<string[]> {\n    const hints = await readHints(join(STATE_DIR, \"hints.json\"));\n    return [...this.config.hiddenModels, ...hintHiddenModels(hints, this.providerId)];\n  }\n\n  /**\n   * The Settings card's Models block: one entry per mount, this box and every ssh box, each with\n   * its provider id (the switches' key), its host (null for this box) and its `pickerModels`.\n   * A mount whose catalog read fails is listed empty rather than failing the others.\n   */\n  async pickerBoxes(): Promise<\n    Array<{\n      provider: string;\n      host: string | null;\n      models: PickerRow[];\n      custom: CustomModel[];\n      route: Route;\n    }>\n  > {\n    return Promise.all(\n      [...ClaudeCodeAdapter.mounts(this)].map(async (mount) => ({\n        provider: mount.providerId,\n        host: mount.config.sshHost || null,\n        models: await mount.pickerModels().catch(() => []),\n        // The entries added in Settings, each of which the block can resize and remove. Config entries\n        // are not here: Settings cannot remove what the profile's config adds.\n        custom: await mount.savedCustomModels().catch(() => []),\n        // Where the box's traffic goes, for the block's opening line and each row's note.\n        route: await mount.route().catch((): Route => ({ state: \"unknown\" })),\n      })),\n    );\n  }\n\n  /**\n   * Tell dsh every mount's picker changed, the event dsh's own providers send when their lineup\n   * moves (`llm/models-updated`): the composer's picker reloads `listModels` on it, so a model\n   * switched off in Settings leaves the open menu at once instead of at the next tab reload. One\n   * emit per mount, since each is its own provider route; a host without `emit` is left alone.\n   */\n  modelsUpdated() {\n    for (const mount of ClaudeCodeAdapter.mounts(this))\n      mount.ctx.emit?.(\"llm/models-updated\", mount.providerId);\n  }\n\n  /**\n   * One mount's model list: every row the catalog and settings.json would offer, hidden or\n   * not, so a hidden model can be switched back on. `locked` marks a row the plugin config hides,\n   * which the switch cannot undo; `hidden` is that switch's answer either way. `off` marks a row\n   * the picker leaves out because of where the box's traffic goes (`mergeCatalog`'s route\n   * filter), whatever its switch says: a model only a router answers for while the box talks to\n   * Anthropic, or one of Claude's own while a router has renamed the aliases. Default is left\n   * out, since it is never hidden.\n   */\n  async pickerModels(): Promise<PickerRow[]> {\n    await this.cliSeed;\n    const picker = await this.pickerSettings();\n    const models = await getCatalog(undefined, this.cliModels, picker);\n    const routed = new Set(\n      (await getCatalog(undefined, this.cliModels, picker, await this.routeFilter())).map(\n        (m) => m.id,\n      ),\n    );\n    const shown = new Set(\n      withoutHiddenModels(models, await this.hiddenModelIds()).map((m) => m.id),\n    );\n    const unlocked = new Set(\n      withoutHiddenModels(models, this.config.hiddenModels).map((m) => m.id),\n    );\n    return models\n      .filter((m) => m.id !== \"default\")\n      .map((m) => {\n        const row: PickerRow = {\n          id: m.id,\n          name: m.name,\n          hidden: !shown.has(m.id),\n          locked: !unlocked.has(m.id),\n          off: !routed.has(m.id),\n          window: m.contextWindow,\n        };\n        if (m.routers !== undefined) row.routers = m.routers;\n        return row;\n      });\n  }\n\n  /** After a `result` frame: remember a login failure for the card, and name the box's providers\n   *  logged out so the picker stops offering them; a turn that succeeded clears both. */\n  noteTurnLogin(sessionId: string, result: ResultFrame) {\n    if (!isLoginFailure(result)) {\n      if (!result.is_error) {\n        this.loginNeeded.delete(sessionId);\n        this.publishAsides(sessionId);\n      }\n      return;\n    }\n    // The key that was refused came from a settings file, not from the login: a router's, or a\n    // gateway's. The login is as good as it was, and calling the box logged out took the model\n    // menu away and sent the owner to log in again for nothing (2026-11-10).\n    // The same for any turn a router answered, whatever key it sent.\n    const held0 = this.processes.get(registryKey(this.providerId, sessionId));\n    if (held0?.prep?.settingsKey || held0?.prep?.via !== undefined) return;\n    const label = this.hostLabelFor(sessionId);\n    // This box is the empty string here and in loginDone/logoutBox, one spelling for the compare.\n    const host = label ?? \"\";\n    this.loginNeeded.set(sessionId, { host, label: label ?? hostname() });\n    this.publishAsides(sessionId);\n    // The process that failed carries no usable login in its environment, and it stays alive\n    // between turns: reused, it fails again with the token the panel has since stored (seen\n    // 2026-09-13: card login said done, the next message was still logged out). Marked stale, the\n    // next prompt replaces it and the fresh spawn reads the token.\n    const held = this.processes.get(registryKey(this.providerId, sessionId));\n    if (held?.alive) held.staleContext = true;\n    // Every provider whose turns run on that box: this box's own, or the box's saved instance. A\n    // remote workspace's turn from a local provider says nothing about the local login.\n    // ponytail: a panel token the box refused stays on disk until the owner logs out or in again;\n    // deleting it here could drop a good newer token on a process spawned before it was written.\n    for (const mount of ClaudeCodeAdapter.mounts(this))\n      if ((mount.config.sshHost || \"\") === host) mount.setLoggedIn(false);\n  }\n\n  /** Log out on `host` (this box when empty) cuts the cord: every live Claude on that box is killed,\n   *  so nothing keeps answering on a login that is gone. A process that loaded the login at start\n   *  would otherwise carry it in memory until it exited. Each session resumes from its transcript on\n   *  its next message, which then fails for want of a login and shows the card. */\n  logoutBox(host: string) {\n    for (const mount of ClaudeCodeAdapter.mounts(this)) {\n      if ((mount.config.sshHost || \"\") !== host) continue;\n      for (const [key, p] of mount.processes) {\n        if (!key.startsWith(`${mount.providerId}:`)) continue;\n        p.kill();\n        mount.processes.delete(key);\n      }\n      mount.setLoggedIn(false);\n    }\n  }\n\n  /** Live Claude processes on `host` (this box when empty), across every mount there. The row shows\n   *  the count when the box reads logged out: those still answer on the login they loaded at start. */\n  liveCount(host: string): number {\n    let n = 0;\n    for (const mount of ClaudeCodeAdapter.mounts(this)) {\n      if ((mount.config.sshHost || \"\") !== host) continue;\n      for (const [key, p] of mount.processes)\n        if (key.startsWith(`${mount.providerId}:`) && p.alive) n++;\n    }\n    return n;\n  }\n\n  /** A panel login on `host` (this box when empty) succeeded: its providers list models again and\n   *  the cards for sessions on that box read done. */\n  loginDone(host: string) {\n    for (const mount of ClaudeCodeAdapter.mounts(this))\n      if ((mount.config.sshHost || \"\") === host) mount.setLoggedIn(true);\n    for (const [sid, need] of this.loginNeeded)\n      if (need.host === host) {\n        this.loginNeeded.delete(sid);\n        this.publishAsides(sid);\n      }\n  }\n\n  /** Every mounted instance, this one included: at boot or in a test it may not be in the shared\n   *  registry yet. */\n  private static mounts(self: ClaudeCodeAdapter): Set<ClaudeCodeAdapter> {\n    // SAFETY: the registry symbol is this plugin's own key on globalThis, typed here once\n    const g = globalThis as typeof globalThis & {\n      [ADAPTER_CURRENT]?: Map<string, ClaudeCodeAdapter>;\n    };\n    return new Set<ClaudeCodeAdapter>([self, ...(g[ADAPTER_CURRENT]?.values() ?? [])]);\n  }\n\n  /** No picker filter here: the allowlist curates what the picker offers, and the CLI keeps a\n   *  session's own model when the allowlist excludes it rather than failing to resolve it.\n   *\n   *  The missing `context` is deliberate; see `prepareCall` below for why.\n   */\n  /**\n   * Full metadata, capacity included, the same answer `prepareCall` gives. dsh reads a model's\n   * window through both methods: `prepareCall` feeds the context ring, `resolveModel` feeds\n   * `llm.resolveModelInfo()`, which `dsh-compaction-basic` multiplies by its threshold ratio.\n   *\n   * From 2026-09-14 to 2026-10-28 this method withheld the capacity on purpose, which switched\n   * dsh's automatic compaction off for these routes: dsh measures its own session surface, which\n   * keeps growing because `resume` sends the CLI only the tail, while Claude Code compacts its own\n   * context out of dsh's sight, so dsh compacted on top of it off a number that did not describe\n   * the CLI's context (22 times in one day, ~100 s of Opus each). dsh's pre-step hook tolerated the\n   * silence: it warned once and carried on.\n   *\n   * dsh 0.2.2-alpha.2 added a second reader that does not: its `agent/request` hook prices a model\n   * switch against the target's capacity and fails the whole request when there is none, so every\n   * switch between two Claude models answered \"Cannot switch to claude-code/…: no context capacity\"\n   * and the typed message was lost. Reporting the window is what dsh's contract asks for, so it is\n   * reported. dsh's compaction then ran again on these routes: dsh prices the prompt the CLI last\n   * reported, which compacting its own copy never lowers, so past 80% of a 1M window it ran before\n   * every step (33 one-shot summaries in one teammate's turns, 2026-11-01). `cliCompaction` now\n   * answers it with Claude Code's own `/compact` (`compactionFromCli`).\n   */\n  override async resolveModel(provider: string, model: string, _signal?: AbortSignal) {\n    return this.fullModelInfo(provider, model);\n  }\n\n  /** The window for the context ring: `request/context` carries it to the token meter, and this\n   *  plugin's own readouts are injected into that ring. */\n  override async prepareCall(provider: string, model: string, _signal?: AbortSignal) {\n    return {\n      model: await this.fullModelInfo(provider, model),\n      stream: (options: GenerateOptions) => this.stream(options),\n    };\n  }\n\n  /** Full metadata for one model, capacity included: the single source both methods above narrow. */\n  private async fullModelInfo(provider: string, model: string): Promise<LlmResolvedModelInfo> {\n    const picker = await this.pickerSettings();\n    // With the picker's own rows in the list: a model only a `customModels` entry or a\n    // `modelPicker.options` row names is in no catalog, and with no row it resolved without a\n    // window, which dsh answers with \"no context capacity\" on the switch to it.\n    // The two filters are left out: they shape the listing, and a session already on a model\n    // the allowlist excludes keeps resolving it, as the terminal does.\n    const rows = picker && { ...picker, availableModels: undefined, replaceBuiltInOptions: false };\n    // No route either: a session on a model the route filter leaves out keeps resolving it.\n    const models = await getCatalog(undefined, this.cliModels, rows);\n    const cap = picker?.modelEffortCaps?.[model] ?? picker?.maxEffortLevel;\n    return resolveModelInfo(provider, model, models, cap);\n  }\n\n  /**\n   * Every model the mount `provider` names can still name, whatever its listing leaves out right\n   * now: the lineup, settings.json's rows and the added models, with no allowlist, no route\n   * filter and no hide switches. This is what a remembered model is judged against (a\n   * workspace's last model, the new-session default): a model the picker is not showing at the\n   * moment is not a retired one, and treating it as retired would move a workspace to another\n   * model each time a router is switched. A provider no mount carries is judged against this\n   * mount, which is what the callers did before they could name one.\n   */\n  async offeredModels(provider?: string): Promise<Array<{ id: string; name: string }>> {\n    const mount =\n      [...ClaudeCodeAdapter.mounts(this)].find((m) => m.providerId === provider) ?? this;\n    await mount.cliSeed;\n    const picker = await mount.pickerSettings();\n    const rows = picker && { ...picker, availableModels: undefined, replaceBuiltInOptions: false };\n    return (await getCatalog(undefined, mount.cliModels, rows)).map((m) => ({\n      id: m.id,\n      name: m.name,\n    }));\n  }\n\n  /** Get the effective permission mode for a session, checking for an override first. */\n  getPermissionMode(sessionId: string, accessMode: string | undefined): string {\n    const override = this.permissionModes.get(sessionId);\n    if (override !== undefined && override !== null) {\n      // An override that is no longer allowed under the current ceiling must not win.\n      const ceiling = permissionModeFor(this.config, accessMode);\n      // SAFETY: permissionModeFor returns a known PermissionMode value from its mapping table.\n      const allowed = isPermissionMode(ceiling)\n        ? modesUpTo(ceiling as PermissionMode)\n        : PERMISSION_MODES;\n      // SAFETY: override came from the adapter's own permissionModes map which only stores valid modes.\n      if (allowed.includes(override as PermissionMode)) return override;\n    }\n    return permissionModeFor(this.config, accessMode);\n  }\n\n  /** The working directory a session runs in, read from its header, or undefined when the session is unknown or its header throws (a detached session cannot be read). */\n  sessionCwd(sessionId: string): string | undefined {\n    try {\n      return this.ctx.sessions.get(asSessionId(sessionId))?.header?.cwd;\n    } catch {\n      return undefined;\n    }\n  }\n\n  /** Emit a names-prefixed log line at the given level, swallowing the error cordis throws when the\n   * logger is reached from an inactive scope. A log line is not worth crashing on. */\n  log(level: string, message: string) {\n    try {\n      this.ctx.logger[level]?.(`dsh-oh-my-claude: ${message}`);\n    } catch {\n      // cordis throws on service access from an inactive scope; a log line is not worth that\n    }\n  }\n\n  /** A copy of the image under the plugin's state dir, named by attachment id with the extension\n   *  its media type calls for: dsh's own stored object has no extension, and Claude Code's Read\n   *  decides image-or-text by the name. Written once per attachment; a failure just leaves the\n   *  image inline-only, as before. */\n  async keepImageCopy(ref: ImageAttachmentRef, data: ArrayBuffer): Promise<string | undefined> {\n    // dsh's ids read `sha256:<hex>`; the hex alone is the file name, and anything else is refused\n    // rather than written under a name the id could steer.\n    const ext = IMAGE_EXT.get(ref.mediaType);\n    const stem = ref.attachmentId.replace(/^sha256:/, \"\");\n    if (!ext || !/^[A-Za-z0-9_-]+$/.test(stem)) return undefined;\n    const dir = join(process.env.DSH_OMC_STATE_DIR ?? STATE_DIR, \"attachments\");\n    const path = join(dir, `${stem}.${ext}`);\n    try {\n      await access(path);\n      return path;\n    } catch {\n      // not there yet\n    }\n    try {\n      await mkdir(dir, { recursive: true });\n      await writeFile(path, Buffer.from(data));\n      return path;\n    } catch (error: unknown) {\n      this.log(\"warn\", `image copy for ${ref.attachmentId} not written: ${String(error)}`);\n      return undefined;\n    }\n  }\n\n  /** The copy itself, as a field so the offline suite can stand in for the ssh. */\n  copyToBox = (host: string, localPath: string, farName: string, capMs: number): Promise<string> =>\n    copyToAt({ sshHost: host }, localPath, farName, capMs);\n  /** Far paths of what this process has already copied, by box and local path.\n   *  ponytail: never forgotten, so a copy deleted on the box stays \"there\" until dsh restarts. */\n  private onBoxAlready = new Map<string, string>();\n  /** One attachment's path on `host`, copied there the first time it is asked for. */\n  async onBox(host: string, localPath: string, farName: string, capMs: number): Promise<string> {\n    const key = `${host}\\n${localPath}`;\n    const known = this.onBoxAlready.get(key);\n    if (known !== undefined) return known;\n    const far = await this.copyToBox(host, localPath, farName, capMs);\n    this.onBoxAlready.set(key, far);\n    return far;\n  }\n\n  /** `host` is the box the turn runs on, when it is not this PC: the saved copy the note names has\n   *  to be on that box, so it is copied there, and an image that would not copy gets no note (it\n   *  still rides inline) rather than one naming a path that box's claude cannot read. */\n  async loadImages(\n    refs: ImageAttachmentRef[],\n    signal: AbortSignal | undefined,\n    host?: string,\n    capMs = COPY_CAP_MS,\n  ): Promise<LoadedImage[]> {\n    const store = this.ctx.attachments;\n    if (!store || refs.length === 0) return [];\n    const out: LoadedImage[] = [];\n    for (const ref of refs) {\n      try {\n        const stored = await store.readImage(ref, signal);\n        const kept = await this.keepImageCopy(ref, stored.data);\n        let path = kept;\n        if (kept && host)\n          try {\n            path = await this.onBox(host, kept, basename(kept), capMs);\n          } catch (error: unknown) {\n            path = undefined;\n            this.log(\"warn\", `image ${ref.attachmentId} not on ${host}: ${errorText(error)}`);\n          }\n        const byPath = oversize(ref) && path !== undefined;\n        if (byPath)\n          this.log(\n            \"info\",\n            `image ${ref.attachmentId} is ${ref.width}x${ref.height}, over ${MAX_IMAGE_SIDE}px; sent by path, not inline`,\n          );\n        out.push({\n          mediaType: ref.mediaType,\n          data: byPath ? \"\" : Buffer.from(stored.data).toString(\"base64\"),\n          attachmentId: ref.attachmentId,\n          path,\n        });\n      } catch (error: unknown) {\n        this.log(\n          \"warn\",\n          `skipping image ${ref.attachmentId ?? \"unknown\"}: ${error instanceof Error ? error.message : String(error)}`,\n        );\n      }\n    }\n    return out;\n  }\n\n  /** A dsh fork of a Claude session becomes a Claude fork: the parent's transcript is copied under\n   *  the new id, cut at the forked turn. True when a copy was made. */\n  async forkTranscript(options: GenerateOptions, cwd: string, id: string): Promise<boolean> {\n    let header;\n    try {\n      header = options.sessionId ? this.ctx.sessions.get(options.sessionId)?.header : undefined;\n    } catch {\n      return false;\n    }\n    const parentId = header?.parentSession;\n    if (!parentId || header?.origin === \"subagent\") return false;\n    const parentCwd = this.sessionCwd(parentId) ?? cwd;\n    const parentClaude = (await claudeSessionExists(this.claudeHome, parentCwd, parentId))\n      ? parentId\n      : claudeSessionId(parentId);\n    let text;\n    try {\n      text = await readFile(\n        join(this.claudeHome, \"projects\", projectDirName(parentCwd), `${parentClaude}.jsonl`),\n        \"utf8\",\n      );\n    } catch {\n      return false;\n    }\n    // ponytail: prompt counting assumes one Claude prompt per dsh user turn; a turn dsh skipped\n    // as already-forwarded (see dropSent) shifts the cut by one.\n    const keep =\n      userPromptCount(options.messages) - userPromptCount(afterLastAssistant(options.messages));\n    const dest = join(this.claudeHome, \"projects\", projectDirName(cwd), `${id}.jsonl`);\n    try {\n      await mkdir(dirname(dest), { recursive: true });\n      await writeFile(dest, forkTranscriptText(text, parentClaude, id, keep));\n    } catch (error) {\n      this.log(\"warn\", `fork transcript copy failed: ${errorText(error)}`);\n      return false;\n    }\n    await rememberStarted(id, true);\n    this.log(\"info\", `forked claude session ${parentClaude} -> ${id} (${keep} prompts kept)`);\n    return true;\n  }\n\n  /** Everything one turn needs: spawn args + spec for the long-lived process, and the stdin line for this turn. */\n  // SAFETY: options shape from dsh LlmAdapter.generate() contract\n  async prepare(\n    options: GenerateOptions,\n    { forceFresh = false }: { forceFresh?: boolean } = {},\n  ): Promise<TurnPrep> {\n    // Title/compaction one-shots run from a scratch dir so their transcripts never show up in a\n    // workspace's Claude Code session list.\n    const cwd = options.purpose\n      ? await auxCwd()\n      : (options.sessionId && this.sessionCwd(options.sessionId)) || process.cwd();\n    // Probe the binary that will actually run: a box's own claude over ssh when this provider is an\n    // SSH box, or when a remote-workspace cwd routes this local provider's session to a box; the local\n    // claude otherwise. A one-shot (title/compaction) always runs locally, so it never probes remote.\n    const targetHost = boxFor(\n      this.config.sshHost,\n      options.purpose ? undefined : remoteWorkspaceFor(cwd)?.host,\n    );\n    if (!options.purpose && isOrphanedStandIn(cwd))\n      throw new LlmError(\n        `This session belongs to a remote workspace that was removed (${basename(cwd)}), so it has no box to run on. Add the same folder on the same box again from the sidebar's Add workspace, and the session continues there.`,\n        \"PROVIDER_ERROR\",\n      );\n    const cli = await probeCli(execFile, this.commandFor(targetHost), targetHost);\n    if (!this.loggedVersion) {\n      this.loggedVersion = true;\n      this.log(\"info\", `claude ${cli.version}, stdin input ${usesStdin(cli.flags) ? \"on\" : \"off\"}`);\n    }\n    // Which binary a turn was measured against, once per target. The plugin's logger goes to dsh's\n    // console, which nothing on a box keeps; resume.log is the plugin's own file and is where a\n    // \"wrong flags for that box\" report can be answered with evidence instead of a guess.\n    if (!this.probeTraced.has(targetHost ?? \"\")) {\n      this.probeTraced.add(targetHost ?? \"\");\n      void trace(\n        join(this.stateDir, \"resume.log\"),\n        `probe ${targetHost ?? \"local\"}: claude ${cli.version}, ${cli.flags?.size ?? \"unknown\"} flags, cwd ${cwd}`,\n      );\n    }\n    let session;\n    const temporary = Boolean(options.sessionId) && this.temporary.has(options.sessionId ?? \"\");\n    if (!options.purpose && this.config.resume && options.sessionId && !temporary) {\n      // A dsh session opened from a Claude Code transcript carries the Claude id itself.\n      const own = await claudeSessionExists(this.claudeHome, cwd, options.sessionId);\n      const id = own ? options.sessionId : claudeSessionId(options.sessionId);\n      let known =\n        own ||\n        (await loadStarted()).has(id) ||\n        (await claudeSessionExists(this.claudeHome, cwd, id));\n      if (!known && !forceFresh) known = await this.forkTranscript(options, cwd, id);\n      session = { id, resuming: known && !forceFresh };\n    }\n    // One small file read per turn, next to a process spawn. No cache: the Settings card writes\n    // this file, and a stale set is a switch that visibly does nothing.\n    const hints = await readHints(join(this.stateDir, \"hints.json\"));\n    const drops = contextDrops(hints);\n    // Asked of the base URL the CLI will really use, which settings.json can set over the head of\n    // dsh's own environment: with a router there and a forwarding proxy exported, the exported\n    // one's answer would tell the CLI its router is Anthropic.\n    // Read for this workspace, not for the mount: its own settings files can set another address.\n    const here = this.config.sshHost || remoteWorkspaceFor(cwd) ? undefined : cwd;\n    const inForce = routeEnvIn(await this.claudeEnv(here)).baseUrl;\n    const forwards = await detectFirstParty(inForce);\n    this.proxyFirstParty = wantsFirstParty(hints, forwards);\n    const settingsKey = here === undefined ? undefined : await this.settingsKey(here);\n    // Answered by something that is not Anthropic: the turn is tagged, so its record is kept\n    // apart from Claude's in everything that adds up money (`TurnRecord.via`). Only when the\n    // endpoint said so; one that did not answer, and one the owner vouched for, are not tagged.\n    const routedTo = proxyBaseUrl(inForce);\n    let via: string | undefined;\n    if (here !== undefined && routedTo && forwards === false && firstPartyMode(hints) !== \"on\") {\n      try {\n        via = new URL(routedTo).host;\n      } catch {\n        via = routedTo;\n      }\n    }\n    // A turn on a box is tagged by that box's own answer: its settings and its loopback, asked\n    // there. A box that could not be read, or whose endpoint did not answer, tags nothing.\n    const far = targetHost === undefined ? undefined : await boxRouteOf(targetHost);\n    const farRoute = far && boxRouteState(far);\n    if (farRoute?.state === \"routed\") via = farRoute.host;\n    const turns = selectTurns(options.messages, session?.resuming ?? false, this.providerId);\n    let prompt = buildPrompt(turns, drops);\n    // A turn on a box reads that box's disk, so what was attached here follows it there.\n    if (targetHost)\n      prompt = await relayFileHandles(\n        prompt,\n        (local, farName) => this.onBox(targetHost, local, farName, COPY_CAP_MS),\n        (level, message) => this.log(level, message),\n      );\n    const stdin = usesStdin(cli.flags);\n    const images = stdin ? await this.loadImages(imageRefs(turns), options.signal, targetHost) : [];\n    // Where each image lives on disk, after the prompt: the inline copy lets Claude see it, the\n    // note lets it Read, edit or delegate it.\n    const notes = attachmentNotes(turns, images);\n    if (notes) prompt = `${prompt}\\n\\n${notes}`;\n    const model = options.purpose === \"session-title\" ? this.config.titleModel : options.model;\n    const accessMode = accessModeOf(options.messages);\n    if (options.sessionId) {\n      this.accessModes.set(options.sessionId, accessMode);\n      if (approvalsDisabled(options.messages)) this.approvalsOff.add(options.sessionId);\n      else this.approvalsOff.delete(options.sessionId);\n    }\n    const effectivePermissionMode = options.sessionId\n      ? this.getPermissionMode(options.sessionId, accessMode)\n      : undefined;\n    // Hoisted