sSpec = {\n      cwd,\n      model,\n      effort: options.reasoningEffort ?? null,\n      mode: effectivePermissionMode ?? permissionModeFor(this.config, accessMode),\n      sessionId: session?.id ?? null,\n      temporary,\n    };\n    // An environment is fixed at spawn, so the switch joins the spec: a session already running\n    // when it flips is replaced on its next turn and resumes with the window the switch gives.\n    // Local spawns only; the flag does not ride to a box, whose own environment decides.\n    if (this.proxyFirstParty && !this.config.sshHost && !remoteWorkspaceFor(cwd))\n      spec.firstParty = true;\n    // The same for a base URL a settings file sets: see `ClaudeProcessSpec.route`.\n    if (\n      inForce !== undefined &&\n      inForce !== process.env.ANTHROPIC_BASE_URL?.trim() &&\n      !this.config.sshHost &&\n      !remoteWorkspaceFor(cwd)\n    )\n      spec.route = inForce;\n    // On a box it is what keeps the panel login out of a router's hands there (`farEnv`).\n    if (via !== undefined) spec.routed = true;\n    // And for a window the plugin or the user has to state: see `ClaudeProcessSpec.window`.\n    // On an ssh box's own mount the rows are that box's, so its window rides there too, unless\n    // the box states one itself. Not for a remote workspace under this box's mount, whose rows\n    // are this box's and say nothing about the far model.\n    let sized: number | undefined;\n    if (here !== undefined) sized = await this.sizedWindow(model, here);\n    else if (this.config.sshHost && far && !far.ownWindow) sized = await this.rowWindow(model);\n    if (sized !== undefined) spec.window = sized;\n    // Keeper or child joins the spec the same way: a flip of the Settings switch replaces each\n    // running process on its session's next turn, never during one. The switch lives in the\n    // default instance's hints file, which the Settings route writes, so a second instance (an SSH\n    // box, a second login) reads that file too; `readHints` caches by mtime.\n    const boxHints =\n      this.stateDir === STATE_DIR ? hints : await readHints(join(STATE_DIR, \"hints.json\"));\n    const spawnMode = spawnModeFor(\n      this.spawnSetting,\n      boxHints[KEEPER_OFF] === true,\n      process.platform,\n    );\n    if (spawnMode !== \"keeper\") spec.child = spawnMode;\n    return {\n      cwd,\n      args,\n      session,\n      spec,\n      accessMode,\n      input: stdin ? buildInput(prompt, images) : null,\n      drops,\n      sizes,\n      settingsKey,\n      via,\n    };\n  }\n\n  /** Claude slash commands already registered as dsh commands, name → disposer. */\n  readonly bridged = new Map<string, () => void>();\n  /** Whether this box's Claude Code is proven to talk to a router right now, for a spawn that has\n   *  no prepared turn to read it from (the lineup probe, the skill doctor, a one-shot). False when\n   *  the route cannot be read, which is the same as before the panel login was ever withheld. */\n  private async boxRouted(): Promise<boolean> {\n    return (await this.route().catch((): Route => ({ state: \"unknown\" }))).state === \"routed\";\n  }\n\n  /** Moves hides stored before the key named a box onto this mount's key, once: see\n   *  `carriedHides`. Runs at start on the default mount; a store with none is left untouched,\n   *  and a failed read or write leaves it for the next start. */\n  async carryHides(path = join(STATE_DIR, \"hints.json\")): Promise<void> {\n    try {\n      const patch = carriedHides(await readHints(path));\n      if (Object.keys(patch).length === 0) return;\n      await updateHints(path, patch);\n      // The pickers and the Settings rows were built from the store as it was.\n      await this.routeChanged();\n      this.log(\n        \"info\",\n        `carried ${Object.keys(patch).length / 2} model hides over to this box's keys`,\n      );\n    } catch (error) {\n      this.log(\"warn\", `model hides not carried over: ${errorText(error)}`);\n    }\n  }\n\n  /** Pending rows the command bridge queued, so one edited into plain text can leave the queue. */\n  readonly commandRows = new CommandRows();\n  /** Sessions already warned that `toolsInline: false` is ignored on a versioned session format. */\n  readonly rowsRefused = new Set<string>();\n  /** Sessions already warned that dsh had no one to answer an approval. */\n  readonly approvalsUnanswered = new Set<string>();\n  /** Terminal exchanges the watcher found, by dsh session, each shown as one turn of its own. */\n  readonly mirrors = new Map<string, MirrorQueue>();\n  /** Terminal turns being streamed live into an open dsh turn, by dsh session. */\n  readonly streaming = new Map<string, StreamState>();\n  /** Whether terminal exchanges are mirrored into dsh at all; the owner's switch, on by default. */\n  terminalSync = false;\n  /** One transcript watcher per dsh session that finished a turn on this box, by dsh session. */\n  readonly watchers = new Map<string, TranscriptWatch>();\n  /**\n   * This plugin's own commands, which share the `bridged` map so one disposer list covers all of\n   * them. They are never Claude's, so the bridge must not register them as passthroughs and the\n   * catalog file must not carry them: the catalog is the union of what it held and what was\n   * bridged, so once they slipped in, every later boot bridged `/btw` to Claude first and the real\n   * handler saw the name taken and stood down (2026-09-08: \"/btw isn't available in this environment\").\n   */\n  static readonly OWN_COMMANDS = new Set([\"temporary\", \"btw\", \"ultracode\", \"compact\"]);\n  /** dsh session id → what `/ultracode` last asked for, and what the CLI last said about it.\n   *  `confirmed` is absent until a read-back lands. Written to `ultracode.json` on every change, so\n   *  a session keeps its setting across a dsh restart and a relaunch of its process. */\n  readonly ultracode = new Map<string, UltracodeState>();\n  /** The last write of `ult