      "path": "src/keeper.ts",
      "content": "/**\n * Keeper: owns one Claude Code process outside dsh's process tree so a dsh restart never touches\n * it. dsh attaches over a unix socket, sends stdin lines, receives stdout lines; while nobody is\n * attached the keeper buffers Claude's output (bounded) and replays it on the next attach. Started\n * as `node keeper.js <dir>` where `<dir>/spec.json` holds { command, args, cwd, env, sessionId }.\n * Runs under its own systemd user scope when the adapter can arrange it, so a service restart's\n * cgroup kill does not reach it. Line protocol, JSON per line:\n *   client → keeper: { t: \"hello\", acks? } | { t: \"in\", line } | { t: \"ack\", n } | { t: \"kill\" }\n *   keeper → client: { t: \"out\", line, n } | { t: \"err\", line } | { t: \"exit\", code, signal } | { t: \"hello\", pid, claudePid, buffered }\n * A client that says `acks: true` acknowledges each stdout line `n` once a turn has actually used\n * it. Until then the keeper keeps the line, and replays every one not acknowledged to the next\n * client: a dsh that is shutting down still reads Claude's output (it stays attached until it\n * exits) but no turn uses it, and without this the reply it read was gone after the restart\n * (automagik#62). A client without acks gets the old behavior: a line it was sent is gone.\n */\nimport { spawn } from \"node:child_process\";\nimport {\n  appendFileSync,\n  existsSync,\n  mkdirSync,\n  readFileSync,\n  unlinkSync,\n  writeFileSync,\n} from \"node:fs\";\nimport { createServer, type Socket } from \"node:net\";\nimport { join } from \"node:path\";\nimport { createInterface } from \"node:readline\";\n\nconst BUFFER_LINES = 20_000; // ~ a long tool-heavy turn; older lines drop with a notice line\n\ninterface KeeperSpec {\n  command: string;\n  args: string[];\n  cwd: string;\n  env: Record<string, string>;\n  sessionId: string;\n  /** End Claude after this long with no dsh attached and no output from it. Absent in a spec an\n   *  older plugin wrote, which keeps such a keeper running until Claude exits or a client kills it. */\n  orphanMs?: number;\n}\n\n/** sun_path is 108 bytes on Linux with the terminator inside it. */\nconst SOCKET_PATH_MAX = 107;\n\n/** The keeper process body, run in the directory `spawnKeeper` prepared. Exits with code 78\n *  before spawning Claude when the socket path would not fit in `sun_path`. */\nfunction main(dir: string) {\n  // SAFETY: spec.json is written by this plugin's spawnKeeper from a typed object moments earlier\n  const spec = JSON.parse(readFileSync(join(dir, \"spec.json\"), \"utf8\")) as KeeperSpec;\n  const sockPath = join(dir, \"keeper.sock\");\n  const infoPath = join(dir, \"keeper.json\");\n  mkdirSync(dir, { recursive: true });\n  if (existsSync(sockPath)) unlinkSync(sockPath);\n  process.on(\"SIGHUP\", () => {}); // the launching terminal or service may hang up; we stay\n  process.on(\"SIGTERM\", () => {}); // only an explicit kill message ends Claude\n\n  const logPath = join(dir, \"keeper.log\");\n  const log = (line: string) => {\n    try {\n      appendFileSync(logPath, `${new Date().toISOString()} ${line}\\n`);\n    } catch {}\n  };\n  // Linux caps a unix socket path at 108 bytes (sun_path), the last one the terminator, so 107\n  // is the longest path that binds. A state dir deep enough to pass that does not fail as a\n  // length error: listen answers EADDRINUSE, and dsh reads the silence as \"keeper did not\n  // answer\". Refuse before Claude is spawned, with the cause where it is looked for (2026-09-18:\n  // a scratch DSH_OMC_STATE_DIR under a session scratchpad, 159 bytes).\n  const sockBytes = Buffer.byteLength(sockPath);\n  if (sockBytes > SOCKET_PATH_MAX) {\n    log(\n      `socket path is ${sockBytes} bytes, over the ${SOCKET_PATH_MAX}-byte unix socket limit: ${sockPath}`,\n    );\n    process.exit(78); // EX_CONFIG\n  }\n\n  let endedBy: \"client\" | \"child\" | \"keeper-crash\" | \"orphan\" | null = null;\n  let exit: { code: number | null; signal: string | null } | undefined;\n\n  // A keeper that dies takes Claude with it: the next boot cannot reattach to a child whose\n  // pipes belonged to a dead keeper, so it kills the orphan and the session loses its process\n  // (2026-09-06 23:43: `read ECONNRESET` from the socket dsh dropped mid-restart, exit 70,\n  // healthy Claude killed as an orphan). So: log, and stay up as long as the child is up.\n  process.on(\"uncaughtException\", (e) => {\n    log(`uncaughtException: ${e?.stack ?? e}`);\n    if (exit) {\n      endedBy = \"keeper-crash\";\n      try {\n        writeInfo();\n      } catch {\n        // the log line above is the record; never let the crash handler itself throw\n      }\n      process.exit(70);\n    }\n  });\n  process.on(\"unhandledRejection\", (r) => {\n    log(`unhandledRejection: ${r instanceof Error ? r.stack : String(r)}`);\n  });\n\n  // Fixed at start: writeInfo runs again on crash and on child exit, and a `Date.now()` in there\n  // would date the *record*, not the keeper. Boot sorts keeper dirs by this field and kills the\n  // ones it does not adopt, so a keeper writing its exit could outrank a live one and get it killed.\n  const startedAt = Date.now();\n  const child = spawn(spec.command, spec.args, {\n    cwd: spec.cwd,\n    env: spec.env,\n    stdio: [\"pipe\", \"pipe\", \"pipe\"],\n  });\n  // A `claude` that is not on the box's PATH emits `error`, never `exit`. With no listener the\n  // throw would land in the uncaughtException handler above, which stays up while `exit` is unset,\n  // leaving a keeper with no child still listening on its socket, taking prompts nothing reads, and\n  // surviving every restart. Report it as the exit it is.\n  child.on(\"error\", (e: Error) => {\n    if (exit) return; // `close` can follow `error`; the first one to land owns the record\n    exit = { code: -1, signal: null };\n    endedBy ??= \"child\";\n    log(`childSpawnError: ${e.message}`);\n    writeInfo();\n    send({ t: \"exit\", code: -1, signal: null });\n    setTimeout(() => process.exit(0), 3000).unref();\n  });\n  child.stdin.on(\"error\", () => {});\n  child.stdout.on(\"error\", (e) => log(`stdout error: ${e.message}`));\n  child.stderr.on(\"error\", (e) => log(`stderr error: ${e.message}`));\n  let client: Socket | undefined;\n  /** Whether the attached client acknowledges the stdout lines it uses. */\n  let clientAcks = false;\n  const buffer: string[] = [];\n  /** Stdout lines sent to an acknowledging client and not acknowledged yet, by number, in order. */\n  const unacked = new Map<number, string>();\n  let lastOut = 0;\n  let dropped = 0;\n  const attached = () => client !== undefined && !client.destroyed;\n  let orphanTimer: ReturnType<typeof setTimeout> | undefined;\n  /**\n   * Nobody attached and Claude silent for `orphanMs`: the dsh that started this keeper is gone for\n   * good (stopped, or the other app on a shared state dir), so end Claude rather than hold it\n   * forever (#241: keepers 15 to 20 hours old, one for a finished subagent session). Each stdout\n   * line while detached restarts the wait, so a turn still producing output while dsh is down\n   * finishes. Closing stdin is how `claude -p` ends cleanly (exit 0 in 0.4 s on 2.1.318); SIGTERM\n   * and then SIGKILL catch one that does not. Wrong for a silent tool that runs longer than\n   * `orphanMs` while dsh is down: that turn is cut, and the next prompt resumes the transcript.\n   */\n  const endOrphan = () => {\n    if (attached() || exit) return;\n    log(`orphan: nobody attached and no output for ${spec.orphanMs} ms, ending claude`);\n    endedBy = \"orphan\";\n    child.stdin.end();\n    setTimeout(() => {\n      if (!exit) child.kill(\"SIGTERM\");\n    }, 5000).unref();\n    setTimeout(() => {\n      if (!exit) child.kill(\"SIGKILL\");\n    }, 10_000).unref();\n  };\n  /** Restart the orphan wait; nothing while a dsh is attached, after Claude exited, or with no\n   *  orphanMs (a spec from an older plugin). */\n  const armOrphan = () => {\n    clearTimeout(orphanTimer);\n    if (spec.orphanMs && !attached() && !exit) orphanTimer = setTimeout(endOrphan, spec.orphanMs);\n  };\n  armOrphan();\n\n  const send = (msg: object) => {\n    const line = `${JSON.stringify(msg)}\\n`;\n    if (attached()) {\n      client?.write(line);\n      return;\n    }\n    if (buffer.length >= BUFFER_LINES) {\n      buffer.shift();\n      dropped++;\n    }\n    buffer.push(line);\n  };\n  // A stdout line goes out numbered. Detached, it waits in `unacked` like a sent one, so a replay\n  // keeps one order; sent to a client that acknowledges, it stays until acknowledged.\n  const sendOut = (text: string) => {\n    const line = `${JSON.stringify({ t: \"out\", line: text, n: ++lastOut })}\\n`;\n    if (attached()) client?.write(line);\n    else armOrphan();\n    if (attached() && !clientAcks) return;\n    if (unacked.size >= BUFFER_LINES) {\n      const oldest = unacked.keys().next().value;\n      if (oldest !== undefined) unacked.delete(oldest);\n      dropped++;\n    }\n    unacked.set(lastOut, line);\n  };\n  const writeInfo = () =>\n    writeFileSync(\n      infoPath,\n      JSON.stringify({\n        pid: process.pid,\n        claudePid: child.pid,\n        sessionId: spec.sessionId,\n        startedAt,\n        exit: exit ?? null,\n        // Why Claude ended, for the boot that finds this keeper dead: \"client\" means a kill\n        // message from dsh, \"child\" means Claude exited on its own.\n        endedBy,\n      }),\n    );\n  log(`start pid=${process.pid} claudePid=${child.pid}`);\n  writeInfo();\n\n  createInterface({ input: child.stdout, crlfDelay: Infinity }).on(\"line\", sendOut);\n  createInterface({ input: child.stderr, crlfDelay: Infinity }).on(\"line\", (line) =>\n    send({ t: \"err\", line }),\n  );\n  // `close`, not `exit`: `exit` fires before stdout and stderr are drained, and the reader above\n  // emits their remaining lines after it. dsh ends its stream on `t:\"exit\"`, so a turn whose final\n  // `result` frame is still in the pipe would lose it and end as \"claude exited 0: no output\".\n  child.on(\"close\", (code, signal) => {\n    if (exit) return; // a spawn error already reported this child; do not report it twice\n    exit = { code, signal };\n    endedBy ??= \"child\";\n    log(`childExit code=${code} signal=${signal}`);\n    writeInfo();\n    send({ t: \"exit\", code, signal });\n    // Give an attached client time to read the exit, then leave.\n    setTimeout(() => process.exit(0), 3000).unref();\n  });\n\n  const server = createServer((sock) => {\n    // One client at a time: a new dsh replaces the old (which is gone anyway after a restart).\n    if (client && !client.destroyed) client.destroy();\n    client = sock;\n    clientAcks = false;\n    clearTimeout(orphanTimer);\n    sock.on(\"error\", () => {});\n    log(`attach buffered=${buffer.length} unacked=${unacked.size} dropped=${dropped}`);\n    sock.on(\"close\", () => {\n      if (client === sock) {\n        client = undefined;\n        log(`detach buffered=${buffer.length} unacked=${unacked.size} dropped=${dropped}`);\n        armOrphan();\n      }\n    });\n    createInterface({ input: sock, crlfDelay: Infinity }).on(\"line\", (raw) => {\n      let msg: { t?: string; line?: string; acks?: boolean; n?: number };\n      try {\n        // SAFETY: the only client is this plugin's attachKeeper; fields are checked before use\n        msg = JSON.parse(raw) as { t?: string; line?: string; acks?: boolean; n?: number };\n      } catch {\n        return;\n      }\n      if (msg.t === \"hello\") {\n        clientAcks = msg.acks === true;\n        sock.write(\n          `${JSON.stringify({ t: \"hello\", pid: process.pid, claudePid: child.pid, buffered: buffer.length + unacked.size, dropped })}\\n`,\n        );\n        if (dropped > 0)\n          sock.write(\n            `${JSON.stringify({ t: \"err\", line: `keeper: ${dropped} output lines dropped while detached` })}\\n`,\n          );\n        // What no turn used yet (sent to the client before, or waiting while detached), then the\n        // rest. A client without acks takes them as delivered.\n        for (const l of unacked.values()) sock.write(l);\n        if (!clientAcks) unacked.clear();\n        for (const l of buffer) sock.write(l);\n        buffer.length = 0;\n        dropped = 0;\n        if (exit) sock.write(`${JSON.stringify({ t: \"exit\", ...exit })}\\n`);\n      } else if (msg.t === \"ack\" && typeof msg.n === \"number\") {\n        if (client === sock) unacked.delete(msg.n);\n      } else if (msg.t === \"in\" && typeof msg.line === \"string\") {\n        if (!exit) child.stdin.write(msg.line);\n      } else if (msg.t === \"kill\") {\n        log(`kill`);\n        if (!exit) {\n          endedBy = \"client\";\n          child.kill(\"SIGTERM\");\n          // The same escalation the plain spawner does (process.ts): a claude inside an\n          // uninterruptible tool ignores SIGTERM, and under a keeper nothing else would end it.\n          const hard = setTimeout(() => {\n            if (!exit) {\n              log(\"kill: no exit after SIGTERM, SIGKILL\");\n              child.kill(\"SIGKILL\");\n            }\n          }, 5000);\n          hard.unref?.();\n        }\n      }\n    });\n  });\n  server.on(\"error\", (e) => log(`server error: ${e.message}`));\n  server.listen(sockPath);\n  process.on(\"exit\", (code) => {\n    log(`exit code=${code} claudeExit=${JSON.stringify(exit ?? null)} endedBy=${endedBy}`);\n    try {\n      unlinkSync(sockPath);\n    } catch {}\n  });\n}\n\nconst dir = process.argv[2];\nif (!dir) {\n  process.stderr.write(\"usage: keeper.js <dir>\\n\");\n  process.exit(2);\n}\nmain(dir);\n"
    },
    {
      "path": "src/mcp.ts",
      "content": "// MCP bridge: exposes the dsh tools visible to a session's agent (subagents, jobs, skills, ...) to\n// the Claude Code process of that session over MCP Streamable HTTP, so a Claude parent can fan out\n// to dsh subagents and they show up under the session like any other child. Shell and file tools are\n// left out: Claude Code has its own. Guarded by a per-process key that only the adapter knows.\n// This is an I/O boundary: JSON-RPC bodies are decoded here.\n//\n// On DSH Desktop the bridge listens on its own loopback port rather than only on dsh's web server:\n// Desktop wraps every web server route in a browser-access gate (403 for anything without the\n// Electron renderer's capability header), which the CLI's MCP client has no way to present, so a\n// bridge served only there is unreachable and Claude sees zero dsh tools. Plain `dsh web` has no\n// gate and keeps the web server route alone, whose port is the one dsh was started on. The web\n// server route is registered either way, and is the fallback when the listener cannot start.\nimport { randomUUID } from \"node:crypto\";\nimport { chmodSync, mkdirSync, readFileSync, writeFileSync } from \"node:fs\";\nimport { createServer, type Server } from \"node:http\";\nimport { dirname, join } from \"node:path\";\nimport type { AddressInfo } from \"node:net\";\nimport type { IncomingMessage, ServerResponse } from \"node:http\";\nimport { readBody } from \"./sessions.js\";\nimport { KEY_HEADER } from \"./mcp-config.js\";\n// The header name lives in mcp-config.ts, a leaf, so the CLI argument builder can read it without\n// importing this module, whose route helpers lead back to the adapter.\nexport { KEY_HEADER } from \"./mcp-config.js\";\nimport { errorText } from \"./process.js\";\nimport type { RelayResult } from \"./process.js\";\nimport type {\n  Agent,\n  DshToolsRegistry,\n  JsonValue,\n  PluginContext,\n  SessionId,\n  ToolSchema,\n} from \"./dsh.js\";\nimport { asSessionId } from \"./dsh.js\";\nimport { resolvedAgent } from \"./adapter/turn.js\";\nimport { PLAN_REFUSAL, planRefuses } from \"./plan-gate.js\";\n\n/** HTTP endpoint path for the MCP bridge handler. */\nexport const MCP_PATH = \"/dsh-oh-my-claude/mcp\";\nconst PROTOCOL = \"2025-06-18\";\nconst BODY_LIMIT = 1024 * 1024;\n/** dsh tools Claude Code already has natively; proxying them would only confuse the model.\n *  `str_replace_editor` is the file editor some presets offer in place of `edit`. */\nexport const HIDDEN = new Set([\n  \"read\",\n  \"write\",\n  \"edit\",\n  \"multi_edit\",\n  \"str_replace_editor\",\n  \"glob\",\n  \"grep\",\n  \"ls\",\n  \"run_code\",\n]);\n\n/** dsh's code-mode tool: under a PTC preset it is the only tool the model may call directly. */\nexport const RUN_CODE = \"run_code\";\n\n/** `run_code` when dsh offers the agent only that tool (a code-mode preset), else undefined. dsh's\n *  registry lists every registered tool either way; the request header holds what the model sees. */\nexport const codeModeTool = (agent: Agent): ToolSchema | undefined => {\n  const offered = agent.session?.requestHeader()?.tools;\n  const only = offered?.length === 1 ? offered[0] : undefined;\n  return only?.name === RUN_CODE ? only : undefined;\n};\n\n/** The dsh tools the bridge offers `agent`: in code mode only `run_code`; otherwise what dsh shows\n *  that agent, minus the ones Claude Code has natively. `open_session` and its two siblings are the\n *  bridge's own, not dsh tools, so code mode leaves them alone; the callers that offer them add them. */\nconst bridgedSchemas = (tools: DshToolsRegistry, agent: Agent): ToolSchema[] => {\n  const runCode = codeModeTool(agent);\n  return runCode ? [runCode] : tools.schemas(agent).filter((t) => !HIDDEN.has(t.name));\n};\n\n/** Bridge-only tool: a new top-level dsh session (sidebar row), not a child of the caller. */\nconst OPEN_SESSION: ToolSchema = {\n  name: \"open_session\",\n  description:\n    \"Start a new top-level dsh session in a workspace and send it a first prompt. It appears in the sidebar as its own session, not under this one, and runs independently. Its replies do not come back here on their own: read them with wait_session. Omit provider and model for the dsh default. Returns the new session id.\",\n  parameters: {\n    type: \"object\",\n    properties: {\n      prompt: { type: \"string\", description: \"The complete first message for the new session.\" },\n      workspaceId: {\n        type: \"string\",\n        description: \"Workspace id to open it in. Default: the workspace of this session.\",\n      },\n      provider: { type: \"string\", description: \"LLM provider id, e.g. claude-code.\" },\n      model: { type: \"string\", description: \"Model id for that provider.\" },\n      reasoningEffort: {\n        type: \"string\",\n        description:\n          \"Thinking level for that model, e.g. low, medium, high. Applied only with provider and model. Default: the provider's default.\",\n      },\n      agentPreset: { type: \"string\", description: \"Agent preset id. Default: the dsh default.\" },\n    },\n    required: [\"prompt\"],\n  },\n};\n\n/** Bridge-only tool: a follow-up into a session that already exists, so a correction or hint keeps\n *  that session's context instead of paying for a new one. dsh's `send_message` cannot do it: it\n *  reaches only the caller's own children and teammates, and an open_session row is neither. */\nconst PROMPT_SESSION: ToolSchema = {\n  name: \"prompt_session\",\n  description:\n    \"Send a follow-up message into an existing dsh session, e.g. one open_session returned. A cold session resumes and keeps its own model and context. mode queue (default) runs it after the current turn; steer injects it into the running turn. The message arrives under a line naming this session as its sender. Returns at once with a cursor: pass it to wait_session as afterSeq to read only the replies that come after this message.\",\n  parameters: {\n    type: \"object\",\n    properties: {\n      sessionId: { type: \"string\", description: \"Target session id, as open_session returned it.\" },\n      prompt: { type: \"string\", description: \"The complete message to send.\" },\n      mode: {\n        type: \"string\",\n        enum: [\"queue\", \"steer\"],\n        description: \"queue (default) waits for the running turn; steer injects into it.\",\n      },\n    },\n    required: [\"sessionId\", \"prompt\"],\n  },\n};\n\n/** Longest wait_session accepts. Claude's MCP client drops a call that stays silent for about\n *  300 s, so a longer wait would lose its answer; Claude calls again instead. */\nconst WAIT_MAX_S = 240;\n/** Most assistant messages one wait_session asks dsh for. dsh's own default, pinned here because\n *  the tool description states it; WAIT_MAX_CHARS is what bounds the size. */\nconst WAIT_MAX_REPLIES = 50;\n/** Most reply text one wait_session returns. Past its MCP output cap Claude Code moves a result\n *  out of the conversation into a file, and below the cap a long one still fills the caller's\n *  context; Chinese runs near a token a character, so the bound is set for that case. */\nconst WAIT_MAX_CHARS = 16_000;\n\n/** Bridge-only tool: the other half of open_session and prompt_session, which return at once. */\nconst WAIT_SESSION: ToolSchema = {\n  name: \"wait_session\",\n  description: `Wait until a dsh session stops working (idle, or waiting on input such as an approval or a question) or the timeout passes, then return its assistant replies, oldest first. afterSeq, from prompt_session, limits them to the replies after that point; without it the session's latest replies come back. At most ${WAIT_MAX_REPLIES} replies and ${WAIT_MAX_CHARS} characters of reply text are returned, the newest kept. The first line ends with the next afterSeq: on timeout, call again with that one, and replies already returned are not repeated. Default timeout 30 s, longest ${WAIT_MAX_S} s.`,\n  parameters: {\n    type: \"object\",\n    properties: {\n      sessionId: { type: \"string\", description: \"Session id, as open_session returned it.\" },\n      afterSeq: {\n        type: \"integer\",\n        description:\n          \"Return only replies after this cursor, as prompt_session or the last wait_session gave it.\",\n      },\n      timeoutSeconds: {\n        type: \"integer\",\n        description: `How long to wait, 1 to ${WAIT_MAX_S}. Default 30.`,\n      },\n    },\n    required: [\"sessionId\"],\n  },\n};\n\n/** The bridge's own tools in the order tools/list offers them. */\nconst OWN_TOOLS = [OPEN_SESSION, PROMPT_SESSION, WAIT_SESSION];\n\n/** A call refused for its arguments. The caller made the mistake, so it gets the message alone:\n *  no stack in the answer, no line in the log. */\nclass BadCall extends Error {}\n\n/** The open_session arguments Claude sends, as far as the bridge reads them. */\ninterface OpenSessionArgs {\n  prompt?: JsonValue;\n  workspaceId?: JsonValue;\n  provider?: JsonValue;\n  model?: JsonValue;\n  reasoningEffort?: JsonValue;\n  agentPreset?: JsonValue;\n}\n\n/** The value when it is a string, else undefined; never a coerced value. */\nconst str = (v: JsonValue | undefined): string | undefined =>\n  typeof v === \"string\" ? v : undefined;\n\n/** The host services openSession needs; all are injected before the bridge mounts. */\ntype OpenHost = Required<\n  Pick<PluginContext, \"sessions\" | \"workspaceRegistry\" | \"sessionController\">\n>;\n\n/**\n * Creates and initializes a new top-level dsh session with an initial prompt.\n * Used by the MCP bridge to fan out sessions from Claude Code to dsh. A provider is applied only\n * with a model; either alone is ignored and the session opens on dsh's default route. A reasoning\n * effort rides on that route and is ignored without it; dsh does not check it against the model,\n * so an effort the model lacks shows up in the new session's first turn, like an unknown model.\n */\nexport async function openSession(\n  ctx: OpenHost,\n  agent: Agent,\n  args: OpenSessionArgs,\n  signal: AbortSignal,\n): Promise<string> {\n  const sessionOf = agent.session;\n  const cwd =\n    sessionOf?.header?.cwd ?? (sessionOf ? ctx.sessions.get(sessionOf.id)?.header?.cwd : undefined);\n  const workspaceId =\n    str(args.workspaceId) ?? ctx.workspaceRegistry.list().find((w) => w.path === cwd)?.id;\n  const agentPreset = str(args.agentPreset);\n  const create: Parameters<OpenHost[\"sessionController\"][\"create\"]>[0] = workspaceId\n    ? { workspaceId }\n    : { cwd };\n  if (agentPreset) create.agentPreset = agentPreset;\n  const { sessionId } = await ctx.sessionController.create(create);\n  const provider = str(args.provider);\n  const model = str(args.model);\n  // From huananhuxu-debug's patch in #250: without it every child ran at the provider's default.\n  const reasoningEffort = str(args.reasoningEffort);\n  // dsh 0.2 dropped `agents.selectForNextRequest`. The controller's `selectModel` is not the\n  // replacement: it also saves the pick as the box's default for every new session, so a model\n  // Claude named for one child would become everyone's. The child's own agent takes the route\n  // instead, the step `selectModel` runs before that save. dsh leaves validation to the caller,\n  // so an unknown model fails in the new session's first turn, where it shows.\n  // A route that cannot be set archives the new, still empty session before the error goes back,\n  // so a failed call leaves no blank row in the sidebar.\n  if (provider && model) {\n    try {\n      const child = resolvedAgent(await ctx.sessionController.resolveAgent(sessionId));\n      // An agent without a model route would leave the session on dsh's default without a word.\n      if (!child.model)\n        throw new Error(`session ${sessionId} has no agent to select ${provider}/${model} on`);\n      child.model.select(\n        reasoningEffort ? { provider, model, reasoningEffort } : { provider, model },\n      );\n    } catch (e) {\n      await ctx.workspaceRegistry.archiveSession(sessionId).catch(() => {});\n      throw e;\n    }\n  }\n  await ctx.sessionController.prompt(\n    {\n      sessionId,\n      requestId: randomUUID(),\n      // Required from dsh 0.1.7: a prompt says whether it queues behind the running turn or\n      // steers into it. A fresh child session has no turn to steer, so it queues.\n      mode: \"queue\",\n      content: [{ type: \"text\", text: String(args.prompt) }],\n    },\n    signal,\n  );\n  return `opened session ${sessionId}${workspaceId ? ` in workspace ${workspaceId}` : ` at ${cwd}`}`;\n}\n\n/** The target session id from a prompt_session or wait_session call. Throws when it is missing or\n *  names the calling session: a session prompting itself would queue behind its own turn, and one\n *  waiting on itself would only ever time out. */\nfunction targetOf(agent: Agent, args: Record<string, JsonValue>, tool: string): SessionId {\n  const id = str(args.sessionId);\n  if (!id) throw new BadCall(`${tool} needs a sessionId`);\n  if (agent.session?.id === id) throw new BadCall(`${tool} cannot target the calling session`);\n  return asSessionId(id);\n}\n\n/** The line prompt_session puts above a message. dsh records the message as a plain user message\n *  with nothing to say who sent it, so without this line the target session, and the owner reading\n *  its transcript, could not tell it from the owner's own typing. The model reads it, so it is not\n *  translated. */\nconst senderLine = (agent: Agent): string =>\n  `[Sent by the agent in dsh session ${agent.session?.id ?? \"unknown\"} through prompt_session, not typed by the user.]`;\n\n/**\n * Sends a follow-up into an existing session (#255, from huananhuxu-debug's patch), under a line\n * naming the calling session as its sender. The cursor is read before the prompt, so replies past\n * it are this message's, plus any the session's running turn finishes meanwhile; reading it does\n * not wake a cold session, and an unknown id fails there with dsh's own \"not found\". dsh's `prompt`\n * resolves the session itself, so a cold one resumes only for a message that is really sent, and\n * keeps its route.\n */\nexport async function promptSession(\n  ctx: Pick<OpenHost, \"sessionController\">,\n  agent: Agent,\n  args: Record<string, JsonValue>,\n  signal: AbortSignal,\n): Promise<string> {\n  const sessionId = targetOf(agent, args, PROMPT_SESSION.name);\n  const prompt = str(args.prompt) ?? \"\";\n  if (!prompt.trim()) throw new BadCall(\"prompt_session needs a non-empty prompt\");\n  const mode = str(args.mode) === \"steer\" ? \"steer\" : \"queue\";\n  const { cursor } = await ctx.sessionController.state({ sessionId }, signal);\n  await ctx.sessionController.prompt(\n    {\n      sessionId,\n      requestId: randomUUID(),\n      mode,\n      content: [{ type: \"text\", text: `${senderLine(agent)}\\n\\n${prompt}` }],\n    },\n    signal,\n  );\n  return `sent to session ${sessionId} (${mode}); afterSeq ${cursor}`;\n}\n\n/** The visible text of one dsh assistant message, its text blocks joined; empty when it has none.\n *  dsh's reasoning blocks carry a `text` field too, so the block type is what is checked: tool\n *  calls and thinking are the session's working, not its answer. */\nfunction replyText(data: JsonValue): string {\n  // SAFETY: dsh event data is JsonValue; an assistant message nests its blocks under `message`\n  const content = (data as { message?: { content?: unknown } } | null)?.message?.content;\n  return (Array.isArray(content) ? content : [])\n    .flatMap((b: unknown) =>\n      b &&\n      typeof b === \"object\" &&\n      \"type\" in b &&\n      b.type === \"text\" &&\n      \"text\" in b &&\n      typeof b.text === \"string\"\n        ? [b.text]\n        : [],\n    )\n    .join(\"\\n\")\n    .trim();\n}\n\n/**\n * Waits on a session through dsh's own `sessionController.wait` and renders its text replies,\n * oldest first, under a status line that ends with the cursor to pass next time. The output is\n * bounded twice: dsh is asked for WAIT_MAX_REPLIES messages at most, and the newest of those are\n * kept up to WAIT_MAX_CHARS, the oldest kept one cut short; a line says when older replies were\n * left out, and nothing here can fetch them afterwards. An afterSeq or timeoutSeconds of the wrong\n * type is refused, since a wait that quietly ran without its cursor returned old replies as if they\n * answered the last message. A timeout outside 1..WAIT_MAX_S seconds is clamped rather than refused.\n */\nexport async function waitSession(\n  ctx: Pick<OpenHost, \"sessionController\">,\n  agent: Agent,\n  args: Record<string, JsonValue>,\n  signal: AbortSignal,\n): Promise<string> {\n  const sessionId = targetOf(agent, args, WAIT_SESSION.name);\n  // A JSON null reads as \"not given\", the way Claude sometimes fills an optional argument.\n  const after = args.afterSeq ?? undefined;\n  if (\n    after !== undefined &&\n    !(typeof after === \"number\" && Number.isSafeInteger(after) && after >= -1)\n  )\n    throw new BadCall(\n      \"wait_session afterSeq must be an integer, -1 or more, as prompt_session or the last wait_session gave it\",\n    );\n  const seconds = args.timeoutSeconds ?? 30;\n  if (typeof seconds !== \"number\")\n    throw new BadCall(`wait_session timeoutSeconds must be a number, 1 to ${WAIT_MAX_S}`);\n  const timeoutMs = Math.round(Math.min(Math.max(seconds, 1), WAIT_MAX_S) * 1000);\n  const { reason, state, output } = await ctx.sessionController.wait(\n    after === undefined\n      ? { sessionId, timeoutMs, maxMessages: WAIT_MAX_REPLIES }\n      : // `+ 0` turns a -0 into 0: dsh refuses -0 as a cursor.\n        { sessionId, timeoutMs, maxMessages: WAIT_MAX_REPLIES, afterSeq: after + 0 },\n    signal,\n  );\n  const status = [\n    `session ${sessionId}: ${reason}`,\n    state.running ? \"running\" : \"not running\",\n    `${state.queue?.length ?? 0} queued`,\n    state.pendingInput.length > 0 ? `${state.pendingInput.length} waiting on input` : \"\",\n    `afterSeq ${state.cursor}`,\n  ].filter(Boolean);\n  const replies: string[] = [];\n  let room = WAIT_MAX_CHARS;\n  let leftOut = output.truncated;\n  // dsh hands the records newest first, so the budget goes to the latest replies.\n  for (const { event } of output.records) {\n    const text = replyText(event.data);\n    if (!text) continue;\n    if (room <= 0) {\n      leftOut = true;\n      break;\n    }\n    // A cut that lands inside an emoji would leave half of its surrogate pair behind.\n    const kept =\n      text.length > room\n        ? `${text.slice(0, room).replace(/[\\uD800-\\uDBFF]$/, \"\")}… (reply cut short)`\n        : text;\n    room -= text.length;\n    replies.unshift(`--- reply at seq ${event.seq} ---\\n${kept}`);\n  }\n  if (leftOut) replies.unshift(\"(older replies left out)\");\n  return [status.join(\", \"), ...(replies.length ? replies : [\"(no replies in range)\"])].join(\"\\n\");\n}\n\n/** Text of a tool's rendered output: text blocks read as text, anything else as JSON. */\nconst textOf = (blocks: JsonValue): string =>\n  (Array.isArray(blocks) ? blocks : [blocks])\n    .map((b) =>\n      b && typeof b === \"object\" && !Array.isArray(b) && typeof b.text === \"string\"\n        ? b.text\n        : JSON.stringify(b),\n    )\n    .join(\"\\n\");\n\n/** One JSON-RPC request as the CLI sends it; only `id`, `method` and `params` are read. */\nexport interface JsonRpcRequest {\n  jsonrpc?: string;\n  id?: JsonValue;\n  method?: string;\n  params?: Record<string, JsonValue>;\n}\n\n/** A tools/call result: text content, flagged when the tool failed. */\ninterface CallResult {\n  content: Array<{ type: \"text\"; text: string }>;\n  isError?: boolean;\n}\n\n/** A JSON-RPC reply: a result, or an error object. */\nexport interface JsonRpcReply {\n  jsonrpc: \"2.0\";\n  id: JsonValue | undefined;\n  result?: object;\n  error?: { code: number; message: string };\n}\n\n/** The JSON-RPC reply for a failed call: a result with `isError` set and the error's text, under\n *  the request's own id. */\nconst errorReply = (id: JsonValue | undefined, e: unknown): JsonRpcReply => ({\n  jsonrpc: \"2.0\",\n  id,\n  result: { content: [{ type: \"text\", text: errorText(e) }], isError: true },\n});\n\n/** What handleRpc needs from the host for one request. */\nexport interface RpcEnv {\n  tools: DshToolsRegistry;\n  agent: Agent;\n  signal: AbortSignal;\n  version: string;\n  open?: (args: OpenSessionArgs) => Promise<string>;\n  /** prompt_session and wait_session; each is offered only when given, like `open`. */\n  prompt?: (args: Record<string, JsonValue>) => Promise<string>;\n  wait?: (args: Record<string, JsonValue>) => Promise<string>;\n  relay?: (\n    name: string,\n    args: Record<string, JsonValue>,\n    signal: AbortSignal,\n  ) => Promise<RelayResult | undefined> | undefined;\n  /** The session CLI's permission mode right now, read once per tools/call so a switch made after\n   *  spawn counts; undefined when unknown, which gates nothing. */\n  mode?: () => string | undefined;\n  log?: (level: string, msg: string) => void;\n}\n\n/** One JSON-RPC request against the tools visible to `agent`. Returns null for notifications. */\nexport async function handleRpc(\n  msg: JsonRpcRequest,\n  { tools, agent, signal, version, open, prompt, wait, relay, mode, log }: RpcEnv,\n): Promise<JsonRpcReply | null> {\n  // The bridge's own tools the host provided, by name; dsh never sees these.\n  const own = new Map<string, (args: Record<string, JsonValue>) => Promise<string>>();\n  if (open) own.set(OPEN_SESSION.name, open);\n  if (prompt) own.set(PROMPT_SESSION.name, prompt);\n  if (wait) own.set(WAIT_SESSION.name, wait);\n  const reply = (result: object): JsonRpcReply => ({ jsonrpc: \"2.0\", id: msg.id, result });\n  /** Writes a failed call to the log with its stack, and returns that stack. */\n  const logged = (e: unknown): string => {\n    const stack = e instanceof Error ? (e.stack ?? e.message) : String(e);\n    log?.(\"warn\", `mcp bridge: ${str(msg.params?.name) ?? msg.method} failed: ${stack}`);\n    return stack;\n  };\n  /** The reply for a failed dsh tool: logged, and answered with the stack, as it always was. */\n  const failed = (e: unknown): JsonRpcReply => errorReply(msg.id, logged(e));\n  if (msg.id === undefined) return null;\n  switch (msg.method) {\n    case \"initialize\":\n      return reply({\n        protocolVersion: str(msg.params?.protocolVersion) ?? PROTOCOL,\n        capabilities: { tools: {} },\n        serverInfo: { name: \"dsh\", version },\n      });\n    case \"ping\":\n      return reply({});\n    case \"tools/list\":\n      return reply({\n        tools: bridgedSchemas(tools, agent)\n          // readOnlyHint is what Claude Code keys concurrency on: without it every MCP call runs\n          // one after another, so parallel subagents would serialize. dsh's own permission\n          // presets still govern what a child may do.\n          .map((t) => ({\n            name: t.name,\n            description: t.description,\n            inputSchema: t.parameters,\n            annotations: { readOnlyHint: true },\n          }))\n          .concat(\n            OWN_TOOLS.filter((t) => own.has(t.name)).map((t) => ({\n              name: t.name,\n              description: t.description,\n              inputSchema: t.parameters,\n              // prompt_session changes another session, so the CLI runs it on its own: batched\n              // beside a wait_session, the wait could otherwise read the session before it lands.\n              annotations: { readOnlyHint: t !== PROMPT_SESSION },\n            })),\n          ),\n      });\n    case \"tools/call\": {\n      const name = str(msg.params?.name) ?? \"\";\n      const rawArgs = msg.params?.arguments;\n      const args: Record<string, JsonValue> =\n        rawArgs && typeof rawArgs === \"object\" && !Array.isArray(rawArgs) ? rawArgs : {};\n      // First, ahead of the bridge's own tools and code mode: plan mode runs hinted tools unasked.\n      if (planRefuses(name, mode?.())) return errorReply(msg.id, PLAN_REFUSAL);\n      const ownTool = own.get(name);\n      if (ownTool) {\n        try {\n          return reply({ content: [{ type: \"text\", text: await ownTool(args) }] });\n        } catch (e) {\n          // The message alone goes back: a stack of plugin and dsh paths tells Claude nothing\n          // about a mistyped session id. A refused argument is not logged either.\n          if (!(e instanceof BadCall)) logged(e);\n          return errorReply(msg.id, e);\n        }\n      }\n      const codeMode = codeModeTool(agent) !== undefined;\n      if (codeMode && name !== RUN_CODE)\n        return errorReply(\n          msg.id,\n          `only ${RUN_CODE} is callable directly in code mode; call ${name} from a ${RUN_CODE} program`,\n        );\n      // run_code is dsh's executor transport, not a registered tool: only a live turn's relay can run it.\n      if (codeMode && !relay) return errorReply(msg.id, `${RUN_CODE} needs a live dsh turn`);\n      const tool = codeMode || HIDDEN.has(name) ? undefined : tools.get(name, agent);\n      if (!tool && !codeMode) return errorReply(msg.id, `unknown tool ${name}`);\n      try {\n        // A live Claude turn takes the call first: dsh then runs the tool itself and renders it\n        // natively (subagent cards, counts, notices). Otherwise execute it here.\n        const relayed = relay ? await relay(name, args, signal) : undefined;\n        if (relayed) {\n          const result: CallResult = {\n            content: [{ type: \"text\", text: relayed.text }],\n          };\n          if (relayed.isError) result.isError = true;\n          return reply(result);\n        }\n        if (!tool) return errorReply(msg.id, `${RUN_CODE} needs a live dsh turn`);\n        const exec = { agent, signal, name, arguments: args, callId: randomUUID() };\n        const returned = await tool.execute(args, exec);\n        const rendered = tool.output?.render ? tool.output.render(args, returned) : returned;\n        return reply({ content: [{ type: \"text\", text: textOf(rendered) }] });\n      } catch (e) {\n        return failed(e);\n      }\n    }\n    default:\n      return {\n        jsonrpc: \"2.0\",\n        id: msg.id,\n        error: { code: -32601, message: `unknown method ${msg.method}` },\n      };\n  }\n}\n\n/** Write a JSON response. An undefined value ends with an empty body rather than the text\n *  `null`. */\nconst send = (res: ServerResponse, status: number, value?: unknown) => {\n  res.writeHead(status, { \"content-type\": \"application/json\", \"cache-control\": \"no-store\" });\n  res.end(value === undefined ? \"\" : JSON.stringify(value));\n};\n\n/** The bridge key outlives a plugin hot reload: running Claude processes were spawned with it. */\nconst KEY_REGISTRY = Symbol.for(\"dsh-oh-my-claude.mcpKey\");\n\n/** What the adapter hands the bridge. */\nexport interface BridgeOptions {\n  log: (level: string, msg: string) => void;\n  version: string;\n  relay?: (\n    sessionId: string,\n    name: string,\n    args: Record<string, JsonValue>,\n    signal: AbortSignal,\n  ) => Promise<RelayResult | undefined> | undefined;\n  /** The permission mode the session's CLI is in right now; feeds the plan-mode gate. */\n  mode?: (sessionId: string) => string | undefined;\n  /** Path of a file holding the bridge key; created once, reused across restarts. */\n  keyFile?: string;\n  /** Path of a file holding the loopback listener's port, so a restart rebinds the same port and\n   *  keeper-mode Claude processes keep their URL. Defaults to `mcp-port` next to `keyFile`.\n   *  Pass `null` to take a fresh ephemeral port on every mount. */\n  portFile?: string | null;\n}\n\n/** A JSON-RPC body is any JSON object; the bridge reads three fields off it. */\nconst asRpc = (body: Record<string, JsonValue>): JsonRpcRequest => ({\n  jsonrpc: str(body.jsonrpc),\n  id: body.id,\n  method: str(body.method),\n  params:\n    body.params && typeof body.params === \"object\" && !Array.isArray(body.params)\n      ? body.params\n      : undefined,\n});\n\n/**\n * The bridge key: the file's contents when they are a valid key, else a fresh key written to the\n * file, so the key survives a restart.\n */\nfunction stableKey(file: string): string {\n  // The key's folder is the plugin's state dir, which also holds saved boxes, login tokens and\n  // keeper files. It is made wherever a store first writes, at whatever mode the umask gives, so\n  // it is closed to other users here, on the one path every start takes.\n  try {\n    mkdirSync(dirname(file), { recursive: true });\n    chmodSync(dirname(file), 0o700);\n  } catch {}\n  try {\n    const k = readFileSync(file, \"utf8\").trim();\n    if (/^[0-9a-f-]{36}$/.test(k)) return k;\n  } catch {}\n  const k = randomUUID();\n  try {\n    writeFileSync(file, k, { mode: 0o600 });\n  } catch {}\n  return k;\n}\n\n/** The mounted bridge, as the adapter holds it. */\nexport interface McpBridge {\n  base: string;\n  key: string;\n  /** Where `base` points: the bridge's own loopback listener under DSH Desktop, else the dsh web\n   *  server route (also when the listener could not start). The CLI's `--mcp-config` URL is built\n   *  off `base` either way. */\n  via: \"loopback\" | \"webserver\";\n  /** The tools `tools/list` will answer that session with, the bridge's own included, so the system\n   *  prompt can name the ones that are really there. Undefined when the session has no live agent\n   *  or dsh refuses the listing; the bridge has nothing for that session either. */\n  toolsFor: (sessionId: string) => ToolSchema[] | undefined;\n}\n\n/** The loopback port remembered from the previous mount, else undefined. */\nfunction readPortFile(file: string): number | undefined {\n  try {\n    const n = Number.parseInt(readFileSync(file, \"utf8\").trim(), 10);\n    if (Number.isInteger(n) && n > 0 && n <= 65535) return n;\n  } catch {}\n  return undefined;\n}\n\n/** Remember the loopback port for the next mount; failures only lose the reuse, never the mount. */\nfunction writePortFile(file: string, port: number): void {\n  try {\n    mkdirSync(dirname(file), { recursive: true });\n    writeFileSync(file, `${port}\\n`);\n  } catch {}\n}\n\n/** One listen attempt against 127.0.0.1. */\nfunction listenOnce(\n  handler: (req: IncomingMessage, res: ServerResponse) => void,\n  port: number,\n): Promise<Server> {\n  return new Promise((resolve, reject) => {\n    const server = createServer(handler);\n    server.once(\"error\", reject);\n    server.listen(port, \"127.0.0.1\", () => {\n      server.off(\"error\", reject);\n      resolve(server);\n    });\n  });\n}\n\n/**\n * The bridge's own listener on 127.0.0.1. The remembered port is tried first so a restart rebinds\n * the same port; when it is taken (a previous generation still holds it, or anything else does),\n * an ephemeral port is taken instead and remembered. Resolves undefined when nothing listens, in\n * which case the caller falls back to the dsh web server route.\n */\nasync function startLoopback(\n  log: (level: string, msg: string) => void,\n  handler: (req: IncomingMessage, res: ServerResponse) => void,\n  portFile: string | undefined,\n): Promise<{ url: string; close: () => void } | undefined> {\n  const wanted = portFile ? readPortFile(portFile) : undefined;\n  const attempts = wanted === undefined ? [0] : [wanted, 0];\n  for (const port of attempts) {\n    try {\n      const server = await listenOnce(handler, port);\n      // SAFETY: a TCP listener bound to 127.0.0.1 reports AddressInfo; string is Unix sockets only\n      const address = server.address() as AddressInfo | string | null;\n      const actual = typeof address === \"object\" && address !== null ? address.port : undefined;\n      if (actual === undefined) {\n        server.close();\n        continue;\n      }\n      if (portFile) writePortFile(portFile, actual);\n      server.on(\"error\", (e) => log(\"warn\", `mcp bridge loopback: ${errorText(e)}`));\n      return { url: `http://127.0.0.1:${actual}`, close: () => server.close() };\n    } catch (e) {\n      log(\n        \"warn\",\n        `mcp bridge: loopback listen on ${port === 0 ? \"an ephemeral port\" : `port ${port}`} failed: ${errorText(e)}`,\n      );\n    }\n  }\n  return undefined;\n}\n\n/** Wires the MCP bridge up once the required services are injected, and keeps the bridge key\n *  stable across dsh restarts so a keeper-mode claude that outlived dsh still authenticates.\n *  Under DSH Desktop, new Claude processes are pointed at the bridge's own loopback listener,\n *  which answers on 127.0.0.1 regardless of the browser-access gate Desktop puts on web server\n *  routes. Everywhere else they get the web server route as before, and no listener is started:\n *  a process that outlives a restart can only reconnect to the URL it was started with, and the\n *  web port is the one address that is fixed by configuration. */\nexport function registerMcpBridge(\n  ctx: PluginContext,\n  { log, version, relay, mode, keyFile, portFile }: BridgeOptions,\n): Promise<McpBridge> {\n  // SAFETY: the key symbol is this plugin's own key on globalThis, typed here once\n  const g = globalThis as typeof globalThis & { [KEY_REGISTRY]?: string };\n  // A key file keeps the bridge key stable across dsh restarts, so a Claude process that outlived\n  // dsh (keeper mode) still authenticates against the new bridge.\n  const key = (g[KEY_REGISTRY] ??= keyFile ? stableKey(keyFile) : randomUUID());\n  const loopPortFile =\n    portFile === null\n      ? undefined\n      : (portFile ?? (keyFile ? join(dirname(keyFile), \"mcp-port\") : undefined));\n  return new Promise((resolve, reject) => {\n    ctx.inject?.(\n      [\"webServer\", \"tools\", \"agents\", \"sessions\", \"sessionController\", \"workspaceRegistry\"],\n      // The body runs async (the loopback listen) but inject takes a sync callback.\n      (host) =>\n        void (async () => {\n          const { webServer, tools, agents, sessions, sessionController, workspaceRegistry } = host;\n          if (!webServer || !tools || !sessionController) return;\n          const openHost: OpenHost = { sessions, workspaceRegistry, sessionController };\n          const serve = async (req: IncomingMessage, res: ServerResponse) => {\n            if (req.headers[KEY_HEADER] !== key) return send(res, 403, { error: \"forbidden\" });\n            if (req.method !== \"POST\") return send(res, 405, { error: \"POST only\" });\n            const sessionId = decodeURIComponent(\n              (req.url ?? \"\").slice(MCP_PATH.length + 1).split(\"?\")[0] ?? \"\",\n            );\n            const agent = agents.get(asSessionId(sessionId));\n            if (!agent) return send(res, 404, { error: `no live agent for session ${sessionId}` });\n            const controller = new AbortController();\n            // Node fires the request's own \"close\" once the body is consumed; the response's\n            // fires when the client actually goes away.\n            res.on(\"close\", () => {\n              if (!res.writableFinished) controller.abort();\n            });\n            try {\n              const msg = asRpc(await readBody(req, BODY_LIMIT));\n              const out = await handleRpc(msg, {\n                tools,\n                agent,\n                signal: controller.signal,\n                version,\n                open: (args) => openSession(openHost, agent, args, controller.signal),\n                prompt: (args) => promptSession(openHost, agent, args, controller.signal),\n                wait: (args) => waitSession(openHost, agent, args, controller.signal),\n                relay: relay\n                  ? (name, args, signal) => relay(sessionId, name, args, signal)\n                  : undefined,\n                mode: mode ? () => mode(sessionId) : undefined,\n                log,\n              });\n              return out === null ? send(res, 202) : send(res, 200, out);\n            } catch (e) {\n              log(\"warn\", `mcp bridge: ${errorText(e)}`);\n              return send(res, 400, { error: errorText(e) });\n            }\n          };\n          // Desktop provides this service from its launcher, before any profile plugin loads, and\n          // gates on it per request; its presence is the gate. Read by name so a host without it\n          // (every plain `dsh web`) answers undefined and runs exactly the path it always has.\n          const gated = host.get?.(\"desktopBrowserAccess\") !== undefined;\n          // The loopback listener is what new Claude processes get there: it answers on 127.0.0.1\n          // no matter what gate sits on the web server routes.\n          const loopback = gated\n            ? await startLoopback(\n                log,\n                (req, res) => {\n                  serve(req, res).catch((e: unknown) =>\n                    log(\"warn\", `mcp bridge loopback: ${errorText(e)}`),\n                  );\n                },\n                loopPortFile,\n              )\n            : undefined;\n          if (loopback) log(\"info\", `mcp bridge: loopback listener on ${loopback.url}`);\n          else if (gated)\n            log(\"warn\", \"mcp bridge: no loopback listener, falling back to the web server route\");\n          // The listen above is awaited, so the scope may be gone by now (a reload mid-mount). An\n          // effect that cannot register would leave the listener holding the port with no owner.\n          try {\n            host.effect?.(() => {\n              const off = webServer.register({ kind: \"prefix\", path: MCP_PATH, handler: serve });\n              return () => {\n                loopback?.close();\n                if (typeof off === \"function\") off();\n              };\n            });\n          } catch (e) {\n            // Rejecting hands the caller its \"bridge unavailable\" path instead of a promise that\n            // never settles.\n            loopback?.close();\n            reject(e instanceof Error ? e : new Error(errorText(e)));\n            return;\n          }\n          resolve({\n            base: loopback?.url ?? `http://127.0.0.1:${webServer.port}`,\n            via: loopback ? \"loopback\" : \"webserver\",\n            key,\n            toolsFor: (sessionId) => {\n              try {\n                const agent = agents.get(asSessionId(sessionId));\n                return agent ? [...bridgedSchemas(tools, agent), ...OWN_TOOLS] : undefined;\n              } catch {\n                return undefined;\n              }\n            },\n          });\n        })(),\n    );\n  });\n}\n"
    },
    {
      "path": "src/process.ts",
      "content": "// One long-lived `claude -p --input-format stream-json` process per dsh session, plus the control\n// channel the Agent SDK uses over the same stream: `control_request` lines from the CLI (permission\n// prompts, user questions) answered with `control_response` lines on stdin.\nimport { spawn } from \"node:child_process\";\nimport { existsSync, mkdirSync, readFileSync, writeFileSync, unlinkSync } from \"node:fs\";\nimport { connect } from \"node:net\";\nimport { homedir } from \"node:os\";\nimport { delimiter, join, sep } from \"node:path\";\nimport { fileURLToPath } from \"node:url\";\nimport { PassThrough, Writable } from \"node:stream\";\nimport { createInterface } from \"node:readline\";\nimport type { AskUserQuestionItem, JsonValue, SubprocessRuntime } from \"./dsh.js\";\nimport type { ContextSizes, ContextSource } from \"./context-sources.js\";\nimport { STATE_DIR } from \"./state.js\";\nexport type { JsonValue } from \"./dsh.js\";\n\n/** Errors reach us as `unknown`; this is the one place they become text. */\nexport const errorText = (e: unknown): string => (e instanceof Error ? e.message : String(e));\n\n/** Text of a Claude tool_result: a string, or the text blocks of a content array; other block\n *  kinds render as their bracketed type. */\nexport function toolResultText(block: { content?: unknown }): string {\n  const c = block.content;\n  if (typeof c === \"string\") return c;\n  if (Array.isArray(c)) return c.map(toolResultBlockText).join(\"\\n\");\n  return \"\";\n}\n\n/** One block of a tool_result content array: its text, or its type in brackets. */\nfunction toolResultBlockText(b: unknown): string {\n  if (typeof b !== \"object\" || b === null || !(\"type\" in b)) return \"[unknown]\";\n  if (b.type === \"text\") return \"text\" in b ? String(b.text) : \"undefined\";\n  return `[${typeof b.type === \"string\" ? b.type : \"unknown\"}]`;\n}\n\n/** Child env on top of the parent's: dsh subagents over MCP can outlive the CLI's default tool timeout. */\n/** What every Claude child gets on top of dsh's environment: a long MCP tool timeout for relayed\n *  dsh tools; file checkpointing, which stream-json runs leave off unless asked, so that the\n *  `rewind_files` control request has something to rewind to; and an entrypoint of the plugin's\n *  own. Left alone, a print-mode CLI records `entrypoint: sdk-cli` in the transcript, and a\n *  terminal `claude --resume` hides every session recorded as sdk-cli, sdk-ts or sdk-py (checked\n *  in 2.1.268), so the dsh sessions never showed in the picker. The CLI keeps any other value as\n *  given, only `cli` is rewritten to sdk-cli in print mode, and an unknown one counts as `other` in\n *  its telemetry and as the plain CLI everywhere else. */\nexport const CHILD_ENV = {\n  MCP_TOOL_TIMEOUT: \"3600000\",\n  CLAUDE_CODE_ENABLE_SDK_FILE_CHECKPOINTING: \"1\",\n  CLAUDE_CODE_ENTRYPOINT: \"dsh-oh-my-claude\",\n  // The CLI stops suggesting the next prompt once any plan window passes its 75% warning (its\n  // rate-limit status `allowed_warning`), and after twenty guesses in a row nobody took, which in\n  // -p mode is every guess, since nothing tells it that Use or Send was clicked. This is its own\n  // override for both, read at startup; it does not lift the mute at a limit actually reached.\n  // Seen on 2.1.308: a Fable session at 82% of its weekly window got no suggestion without it and\n  // one with it. The initialize request still turns suggestions off when the switch is off, since\n  // the CLI checks that first.\n  CLAUDE_CODE_ENABLE_PROMPT_SUGGESTION: \"true\",\n};\n\n/** The privacy switches a person sets in the environment dsh runs in: Claude Code's own telemetry, error-reporting and nonessential-traffic switches, its updater\n *  and bug-report switches, and the cross-tool DO_NOT_TRACK. A local child inherits them through\n *  `childEnv`; a child on another machine starts from that machine's shell, so the remote paths\n *  carry each one that is set here, as set. None is ever invented. */\nexport const FORWARDED_ENV = [\n  \"DISABLE_TELEMETRY\",\n  \"DISABLE_ERROR_REPORTING\",\n  \"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC\",\n  \"DISABLE_AUTOUPDATER\",\n  \"DISABLE_BUG_COMMAND\",\n  \"DO_NOT_TRACK\",\n] as const;\n\n/** The names dsh's subprocess seam leaves out of a child's environment, copied from\n *  `SENSITIVE_ENV_PATTERN` in @deepseek-ai/dsh-subprocess (0.2.2-rc.1); the package is not a\n *  dependency of this plugin. */\nconst SCRUBBED_NAME = /KEY|PASSWORD|SECRET|TOKEN/i;\n\n/**\n * The credential-shaped entries of `base` that dsh's seam would drop, so `spawn: dsh` gives Claude\n * the login and tokens a keeper or a node child gets: `ANTHROPIC_API_KEY`, `ANTHROPIC_AUTH_TOKEN`,\n * cloud keys, and the `GH_TOKEN` and `MAX_THINKING_TOKENS` the CLI also reads (the 2.1.318 binary\n * names 62 variables the pattern matches). `DSH_*` names stay dropped, the seam's other rule; no\n * mode needs them in Claude. Wrong for someone who picked the seam to keep a secret away from\n * Claude: dsh's environment reaches Claude in every mode.\n */\nexport function credentialEnv(base: NodeJS.ProcessEnv) {\n  const out: Record<string, string> = {};\n  for (const [k, v] of Object.entries(base))\n    if (v !== undefined && SCRUBBED_NAME.test(k) && !/^DSH_/i.test(k)) out[k] = v;\n  return out;\n}\n\n/** The FORWARDED_ENV pairs set in `base`, in that order. */\nexport function forwardedEnv(base: NodeJS.ProcessEnv = process.env): [string, string][] {\n  return FORWARDED_ENV.flatMap((key): [string, string][] => {\n    const value = base[key];\n    return value === undefined || value === \"\" ? [] : [[key, value]];\n  });\n}\n\n/** The environment a Claude child runs with: dsh's own, then the plugin's additions, then whatever\n *  the caller passes. CHILD_ENV beats the inherited value on purpose. An `MCP_TOOL_TIMEOUT` that\n *  happens to be in dsh's environment would otherwise cut relayed dsh tools short in one spawn mode\n *  and not the other. A caller that means to override still wins, which is the escape hatch. */\nexport function childEnv(base: NodeJS.ProcessEnv, override?: Record<string, string>) {\n  const env: Record<string, string> = {};\n  for (const [k, v] of Object.entries(base)) if (v !== undefined) env[k] = v;\n  if (process.platform !== \"win32\") env.PATH = withClaudeDirs(env.PATH);\n  Object.assign(env, CHILD_ENV, override ?? {});\n  return env;\n}\n\n/** Where Claude Code's installers put `claude` (the native installer, the old local install, Homebrew,\n *  npm and bun globals, Volta). An app started from the macOS Dock or Finder, DSH Desktop among\n *  them, gets a PATH of `/usr/bin:/bin:/usr/sbin:/sbin`, which holds none of these. */\nexport function claudeDirs(home = homedir()): string[] {\n  return [\n    join(home, \".local\", \"bin\"),\n    join(home, \".claude\", \"local\"),\n    \"/opt/homebrew/bin\",\n    \"/usr/local/bin\",\n    join(home, \".npm-global\", \"bin\"),\n    join(home, \".bun\", \"bin\"),\n    join(home, \".volta\", \"bin\"),\n  ];\n}\n\n/** `path` with every folder from `dirs` it lacks appended, so a name found on the caller's PATH\n *  keeps winning. Appending also lets an npm-installed `claude`, a `#!/usr/bin/env node` script,\n *  find the node that sits beside it. */\nexport function withClaudeDirs(path: string | undefined, dirs = claudeDirs()): string {\n  const have = (path ?? \"\").split(delimiter).filter(Boolean);\n  return [...have, ...dirs.filter((d) => !have.includes(d))].join(delimiter);\n}\n\n/** The absolute path of `command` when it is a bare name found on `path` or in `dirs`, else\n *  `command` unchanged: a path is trusted as given, and a name found nowhere is left for spawn to\n *  fail on with the usual ENOENT. On Windows a bare name matches only `<name>.exe`: npm's global\n *  folder holds an extension-less `#!/bin/sh` shim beside `claude.cmd`, which Windows cannot run,\n *  so for `claude` that folder answers with the binary npm installed under its `node_modules`. */\nexport function resolveCommand(\n  command: string,\n  path = process.env.PATH,\n  dirs = claudeDirs(),\n  exists: (p: string) => boolean = existsSync,\n  platform: NodeJS.Platform = process.platform,\n): string {\n  if (!command || command.includes(\"/\") || command.includes(sep)) return command;\n  const win = platform === \"win32\";\n  const name = win && !/\\.[a-z0-9]+$/i.test(command) ? `${command}.exe` : command;\n  for (const dir of [...(path ?? \"\").split(delimiter).filter(Boolean), ...dirs]) {\n    if (exists(join(dir, name))) return join(dir, name);\n    const npm = join(dir, \"node_modules\", \"@anthropic-ai\", \"claude-code\", \"bin\", \"claude.exe\");\n    if (win && command === \"claude\" && exists(npm)) return npm;\n  }\n  return command;\n}\n\n/** The child process seam this plugin uses: dsh's own spawner and the node one both answer it. */\nexport interface SubprocessHandle {\n  stdin: import(\"node:stream\").Writable;\n  stdout: import(\"node:stream\").Readable;\n  stderr: import(\"node:stream\").Readable;\n  done: Promise<{ exitCode: number | null; signal: string | null }>;\n  terminate(): void;\n  /** The stdout line at `index` (0 for this handle's first line) was used by a turn, or consumed\n   *  on arrival. A keeper keeps a line until then and replays it to the next dsh; a plain child\n   *  has nothing to keep. */\n  ack?(index: number): void;\n}\n\n/** One line of the CLI's stream-json stdout, in the shapes this plugin reads. */\nexport type ClaudeEvent =\n  | {\n      type: \"system\";\n      subtype?: string;\n      /** subtype \"init\": the CLI's slash-command catalog (skills, custom commands, built-ins). */\n      slash_commands?: JsonValue;\n      /** subtype \"init\": where the credential for API requests came from (`ANTHROPIC_API_KEY`,\n       *  `apiKeyHelper`, `none` for the claude.ai login, and the rest of the CLI's enum). */\n      apiKeySource?: string;\n      /** subtype \"init\": every tool name the session has; MCP ones read `mcp__<server>__<tool>`. */\n      tools?: JsonValue;\n      /** subtype \"init\": plugins the CLI could not load, `{plugin,type,message}` each. Present only\n       *  when there are errors; a clean load omits the key. */\n      plugin_errors?: JsonValue;\n      /** subtype \"init\": plugins the CLI loaded with a complaint, `{plugin,type,message}` each\n       *  (a shadowed default folder, a suppressed server). Present only when there are warnings. */\n      plugin_warnings?: JsonValue;\n      /** subtype \"compact_boundary\": `trigger` and `pre_tokens` always, `post_tokens` and\n       *  `duration_ms` when the CLI chose to fill them in. */\n      compact_metadata?: Record<string, unknown>;\n      // subtype \"status\": `status:\"compacting\"` opens the silent summarize stretch; a later frame\n      // with `status:null` carries `compact_result` (\"success\"|\"failed\") and, on failure, `compact_error`.\n      status?: string | null;\n      compact_result?: string;\n      compact_error?: string;\n      // subtype \"memory_saved\": the auto-memory files Claude just wrote; \"memory_recall\": the ones\n      // it pulled into context at the start of a turn.\n      written_paths?: string[];\n      verb?: string;\n      memories?: Array<{ path?: string; scope?: string }>;\n      // subtype \"hook_started\" / \"hook_response\": hook lifecycle events, only emitted when\n      // the process runs with --include-hook-events (SessionStart and Setup always emit).\n      hook_name?: string;\n      hook_event?: string;\n      output?: string;\n      stdout?: string;\n      stderr?: string;\n      exit_code?: number;\n      outcome?: string;\n      // subtype \"task_started\" / \"task_notification\": subagent task lifecycle frames emitted by the CLI.\n      task_id?: string;\n      description?: string;\n      subagent_type?: string;\n      is_backgrounded?: boolean;\n      summary?: string;\n      /** In auto mode a subagent's report goes to the parent as a message and `summary` only says\n       *  so; the report is here, with a `warning` when the CLI cut or altered it (2.1.322). */\n      handback_report?: { text?: string; warning?: string };\n      // subtype \"task_progress\": progress update for a running task, carries usage, last_tool_name, summary and workflow_progress.\n      // subtype \"task_notification\": carries status.\n      last_tool_name?: string;\n      usage?: {\n        input_tokens?: number;\n        output_tokens?: number;\n        cache_read_input_tokens?: number;\n        cache_creation_input_tokens?: number;\n      };\n      workflow_progress?: unknown;\n      // subtype \"task_updated\": the fields of a task that changed. `status` moves through pending,\n      // running, completed, failed, killed and paused; the terminal ones are what a task that dies\n      // without a notification reports.\n      patch?: {\n        status?: string;\n        error?: string;\n        end_time?: number;\n        is_backgrounded?: boolean;\n      };\n      // subtype \"commands_changed\": the whole slash-command catalog again, after a skill or custom\n      // command appeared mid-session. Same shape as init's `slash_commands`.\n      commands?: JsonValue;\n      // subtype \"model_fallback\": the CLI dropped to a weaker model. `content` is display-ready.\n      content?: string;\n      level?: string;\n      trigger?: string;\n      original_model?: string;\n      fallback_model?: string;\n      // subtype \"model_refusal_fallback\": the safety classifier flagged the message and the turn\n      // fell back to a safer model. `direction` \"sticky\" = the session model swapped for the rest of\n      // the conversation; \"retry\"/\"revert\" are one-off. `scope` \"local\" = a subagent, a /btw\n      // side-question or a background fork fell back, and the session model is unchanged.\n      direction?: \"retry\" | \"revert\" | \"sticky\";\n      scope?: \"session\" | \"local\";\n      // The refusal category (\"cyber\", \"bio\", …), an open string; null when neither the API response\n      // nor the fallback block carried one. `api_refusal_explanation` is the model_refusal_no_fallback\n      // sibling's human reason.\n      api_refusal_category?: string | null;\n      api_refusal_explanation?: string | null;\n      // subtype \"model_consent_fallback\": the usage-credit / switch-default gate (secondary to the\n      // refusal frames). `persisted_as_default` true = the switch became the saved default model.\n      original_model_name?: string;\n      persisted_as_default?: boolean;\n      choice?: \"consent\" | \"switch_default\" | \"cancelled\";\n      // subtype \"informational\": a loop banner. `prevent_continuation` marks the ones that ended\n      // the turn early (a Stop hook denying continuation).\n      prevent_continuation?: boolean;\n      // subtype \"permission_denied\": the tool the CLI refused, and why, at the moment of refusal.\n      tool_name?: string;\n      message?: string;\n      decision_reason?: unknown;\n      decision_reason_type?: string;\n      // subtype \"background_tasks_changed\": list of running background tasks.\n      tasks?: unknown;\n      // subtype \"thinking_tokens\": one frame per thinking delta, so the estimate is unthrottled.\n      // `estimated_tokens` is the running total for the *current* thinking block and resets at the\n      // next content_block_start; it is a spinner estimate, not the billed output_tokens.\n      estimated_tokens?: number;\n      estimated_tokens_delta?: number;\n      // subtype \"api_retry\": the CLI is retrying a failed API call (a 429 while a limit holds, a\n      // 5xx, a dropped connection). `error.rate_limits` is set only for a quota 429.\n      attempt?: number;\n      max_retries?: number;\n      retry_delay_ms?: number;\n      error?: {\n        message?: string;\n        status?: number;\n        formatted?: string;\n        rate_limits?: { resets_at?: number; rate_limit_type?: string } | null;\n        /** subtype \"api_error\": set when the failure was the connection itself, not a response. */\n        connection?: string;\n        is_network_down?: boolean;\n      };\n    }\n  | {\n      /** Top-level frame, not a `system` subtype: the CLI emits one per running tool call every 30\n       *  seconds with `heartbeat: true`, and one without it when a subagent retries an API failure. */\n      type: \"tool_progress\";\n      tool_use_id?: string;\n      tool_name?: string;\n      parent_tool_use_id?: string | null;\n      elapsed_time_seconds?: number;\n      heartbeat?: boolean;\n      task_id?: string;\n      subagent_type?: string;\n      subagent_retry?: {\n        agent_id?: string;\n        attempt?: number;\n        max_retries?: number;\n        retry_delay_ms?: number;\n        error_status?: number;\n        error_category?: string;\n      };\n    }\n  | {\n      type: \"stream_event\";\n      event?: ClaudeStreamPartial;\n      /** Set when the frame belongs to a nested agent, as on `assistant` and `user` frames. */\n      parent_tool_use_id?: string | null;\n    }\n  | { type: \"assistant\"; message?: ClaudeAssistantMessage; parent_tool_use_id?: string | null }\n  | {\n      type: \"user\";\n      /** Blocks for a tool result. A plain string for text the CLI wrote itself: a slash\n       *  command's output (`<local-command-stdout>`), the summary that follows a compaction. */\n      message?: { content?: string | ClaudeContentBlock[] };\n      parent_tool_use_id?: string | null;\n      /** What the CLI records beside a tool result. `handbackReport` holds a subagent's report\n       *  when the result text is only the note that it was delivered as a message. */\n      tool_use_result?: { handbackReport?: { text?: string } };\n    }\n  | {\n      type: \"result\";\n      is_error?: boolean;\n      stop_reason?: string;\n      result?: unknown;\n      errors?: unknown[];\n      api_error_status?: number;\n      subtype?: string;\n      usage?: {\n        input_tokens?: number;\n        output_tokens?: number;\n        cache_read_input_tokens?: number;\n        cache_creation_input_tokens?: number;\n      };\n    }\n  | {\n      type: \"rate_limit_event\";\n      // status \"rejected\" with overageStatus \"allowed\" means paid extra usage covers the overflow:\n      // the CLI's own banner shows no limit then (its isUsingOverage), and the turn goes on.\n      rate_limit_info?: {\n        status?: string;\n        resetsAt?: number;\n        rateLimitType?: string;\n        overageStatus?: string;\n        overageResetsAt?: number;\n        isUsingOverage?: boolean;\n      };\n    }\n  | {\n      type: \"control_request\";\n      request_id: string;\n      request?: {\n        subtype?: string;\n        tool_name?: string;\n        input?: Record<string, JsonValue>;\n        tool_use_id?: string;\n        title?: string;\n        description?: string;\n        // subtype \"elicitation\": an MCP server asks the user for structured input.\n        mcp_server_name?: string;\n        display_name?: string;\n        message?: string;\n        mode?: string;\n        url?: string;\n        elicitation_id?: string;\n        requested_schema?: JsonValue;\n      };\n    }\n  | { type: \"control_cancel_request\"; request_id: string }\n  | {\n      type: \"control_response\";\n      request_id: string;\n      response?: { subtype?: string; request_id?: string; response?: unknown; error?: unknown };\n    }\n  | { type: \"timeout\" }\n  /** Queued by the adapter's idle watchdog shortly before it stops a silent process. */\n  | { type: \"idle_warning\"; silentSeconds: number; leftSeconds: number }\n  | RelayEvent;\n\n/** What dsh hands back for a relayed tool call: the text Claude gets, and whether it failed. */\nexport interface RelayResult {\n  text: string;\n  isError?: boolean;\n}\n\n/** A dsh tool call the MCP bridge parks on the live turn; settled when dsh returns its result. */\nexport interface RelayEvent {\n  type: \"dsh_relay\";\n  id: string;\n  name: string;\n  args: Record<string, JsonValue>;\n  resolve: (v: RelayResult) => void;\n  reject: (e: Error) => void;\n}\n\n/** The `message` of an assistant event: the model that wrote it and its content blocks. */\nexport interface ClaudeAssistantMessage {\n  id?: string;\n  model?: string;\n  role?: string;\n  content?: ClaudeContentBlock[];\n}\n\n/** One block of an assistant message; the translator draws a lane for each of these four. */\nexport type ClaudeContentBlock =\n  | { type: \"text\"; text: string }\n  | { type: \"thinking\"; thinking: string }\n  | { type: \"tool_use\"; id: string; name?: string; input?: Record<string, unknown> }\n  | { type: \"tool_result\"; tool_use_id?: string; content?: unknown; is_error?: boolean };\n\n/** One Anthropic streaming event as Claude Code forwards it. Untyped past `type`: only the three\n *  content-block events carry fields the translator reads, and unknown types are logged once. */\nexport interface ClaudeStreamPartial {\n  type: string;\n  index?: number;\n  /** `message_start` only: the message these deltas belong to. */\n  message?: { id?: string };\n  content_block?: { type?: string; id?: string; name?: string };\n  delta?: { text?: string; thinking?: string; partial_json?: string; signature?: string };\n}\n\n/**\n * Node's own spawn, shaped like a dsh `SubprocessHandle` so the process code has one shape to\n * talk to: `stdin`/`stdout`/`stderr` streams, `done` resolving with the exit code, `terminate()`.\n * `envOverride` is merged last so configured values win over the parent's environment.\n */\nexport function nodeSpawner(\n  command: string,\n  args: string[],\n  cwd: string,\n  envOverride?: Record<string, string>,\n): SubprocessHandle {\n  const child = spawn(command, args, {\n    cwd,\n    stdio: [\"pipe\", \"pipe\", \"pipe\"],\n    env: childEnv(process.env, envOverride),\n  });\n  return {\n    stdin: child.stdin,\n    stdout: child.stdout,\n    stderr: child.stderr,\n    done: new Promise((resolve) => {\n      // Node emits `error` on the child for ENOENT, EACCES and a failed fork, and an EventEmitter\n      // `error` with no listener throws. A `claude` that is not on PATH would take the whole dsh\n      // host down with it, every session, not just this one. It reads as an exit here instead.\n      child.on(\"error\", (e: Error) => resolve({ exitCode: -1, signal: e.message }));\n      child.on(\"close\", (exitCode, signal) => resolve({ exitCode, signal }));\n    }),\n    // SIGTERM, then SIGKILL if it is still there. A claude inside an uninterruptible tool, or one\n    // whose own child holds the process group, ignores the first and would otherwise outlive the\n    // session that owned it: an orphan holding the session file and the MCP connections, invisible\n    // to the panel. `unref` so the escalation never keeps this process alive on its own.\n    terminate: () => {\n      child.kill();\n      setTimeout(() => {\n        if (child.exitCode === null && child.signalCode === null) child.kill(\"SIGKILL\");\n      }, 5000).unref();\n    },\n  };\n}\n\n/**\n * dsh's subprocess seam (`ctx.subprocess`). Same shape by definition. The seam owns the whole\n * process tree, so Claude and what it started end when dsh exits. It drops credential-shaped names\n * from the environment it hands a child and keeps the ones the caller passes, so the ones dsh runs\n * with are passed here (`credentialEnv`): an `ANTHROPIC_API_KEY` login keeps working, as it does\n * under a keeper. With a remote provider mounted, Claude Code runs on the remote machine for a\n * remote workspace and those values go with it. `envOverride` is merged last so configured values\n * win.\n */\nexport const seamSpawner =\n  (subprocess: Pick<SubprocessRuntime, \"spawn\">, base: NodeJS.ProcessEnv = process.env): Spawner =>\n  (command, args, cwd, envOverride) =>\n    subprocess.spawn({\n      argv: [command, ...args],\n      cwd,\n      env: {\n        ...credentialEnv(base),\n        ...seamPath(base),\n        ...Object.fromEntries(forwardedEnv(base)),\n        ...CHILD_ENV,\n        ...envOverride,\n      },\n      graceMs: 5000,\n      stdio: { stdin: \"pipe\", stdout: \"pipe\", stderr: \"pipe\" },\n    });\n\n/** The PATH a seam child gets: dsh's own, then the installer folders, as `childEnv` gives a node\n *  child. DSH Desktop started from the macOS Dock has `/usr/bin:/bin:/usr/sbin:/sbin`, where an npm\n *  or Volta `claude` cannot find its `node` and Claude's Bash loses `~/.local/bin`. Nothing on\n *  Windows, or with no PATH in `base` to extend: the seam's own PATH stands then. Wrong for a\n *  remote seam provider: this box's folders go to the other machine, where they are most likely\n *  absent and harmless. */\nfunction seamPath(base: NodeJS.ProcessEnv) {\n  if (process.platform === \"win32\" || base.PATH === undefined) return {};\n  return { PATH: withClaudeDirs(base.PATH) };\n}\n\n/** POSIX single-quote a string for a remote shell: wrap in `'...'`, escaping any embedded quote. */\nexport function shq(value: string): string {\n  return `'${value.replace(/'/g, \"'\\\\''\")}'`;\n}\n\n/** The local `ssh` argv that runs `script` on `host`. BatchMode: key auth only, so a missing key or\n * unknown host fails fast instead of hanging on a prompt. */\n/**\n * The argument list for `ssh <host> <script>`.\n *\n * `--` ends ssh's own option parsing, so the host is always a destination and never an option.\n * Without it, a host that starts with a dash is read as a flag: `-oProxyCommand=<cmd>` makes ssh\n * run `<cmd>` on this machine before it connects anywhere, which is a local command run by anyone\n * who can pass dsh's login, outside every permission mode Claude has. Two routes took the host\n * straight from the request. The check below refuses such a host outright rather than relying on\n * `--` alone, because a refused request says what went wrong and a quietly failed connect does not.\n * Found by a security review, 2026-09-21.\n */\nexport function sshArgs(host: string, script: string) {\n  if (!isSshHost(host)) throw new Error(`not an ssh host: ${JSON.stringify(host.slice(0, 80))}`);\n  return [...SSH_OPTS, \"--\", host, script];\n}\n\n/** A destination ssh can be given safely: `host`, `user@host` or `user@host:port`-free forms,\n *  and never anything ssh would read as an option or that carries whitespace or a control. */\nexport function isSshHost(host: string): boolean {\n  return host.length > 0 && host.length <= 253 && !host.startsWith(\"-\") && !/[\\s\\0]/.test(host);\n}\n\n/** A Unix socket path holds 108 bytes on Linux, and the last one is the terminator. */\nconst SOCKET_PATH_MAX = 107;\n/** `%C` is a SHA-1 in hex, and ssh appends `.` plus 16 random characters while it builds the master. */\nconst CONTROL_NAME = \"cm-\".length + 40 + \".XXXXXXXXXXXXXXXX\".length;\n\n/**\n * Where the multiplex sockets live, or nothing when no directory can hold one.\n *\n * The state dir is one byte too long for a `%C` socket (`~/.local/state/dsh-oh-my-claude/ssh/`\n * plus the name is 108), so every connection through it failed with \"too long for Unix domain\n * socket\" and the panel showed that instead of the box. The runtime dir is short, is on tmpfs and\n * is cleared at logout, which is where a socket belongs; the state dir stays as the fallback for a\n * session without one, and is skipped when it does not fit.\n */\nexport function controlSocketDir(\n  runtime: string | undefined,\n  state: string,\n  make: (dir: string) => void,\n): string | undefined {\n  const candidates =\n    runtime === undefined ? [join(state, \"ssh\")] : [join(runtime, \"omc-ssh\"), join(state, \"ssh\")];\n  for (const dir of candidates) {\n    if (dir.length + 1 + CONTROL_NAME > SOCKET_PATH_MAX) continue;\n    try {\n      make(dir);\n      return dir;\n    } catch {\n      // Unwritable: try the next one, and share nothing rather than fail every ssh.\n    }\n  }\n  return undefined;\n}\nconst SSH_CONTROL_DIR = controlSocketDir(process.env.XDG_RUNTIME_DIR, STATE_DIR, (dir) =>\n  mkdirSync(dir, { recursive: true, mode: 0o700 }),\n);\n\n/**\n * The options every ssh in this plugin carries.\n *\n * BatchMode: key auth only, so a missing key or unknown host fails fast instead of hanging on a\n * prompt. ConnectTimeout bounds the handshake.\n *\n * ControlMaster shares one connection between all of them. Opening the panel on a box costs about\n * 33 remote reads. The CLAUDE.md walk alone is 25 of them, one probe per ancestor directory.\n * Without multiplexing each pays a full TCP connect, key exchange and auth: seconds of dead panel\n * on a LAN, more over a WAN. With it the first read pays that once and the rest reuse the socket,\n * which ControlPersist keeps for a minute after the last one closes.\n *\n * ServerAlive turns a dead network into an error. The session pipe is a long-lived ssh, and a\n * suspend, a Wi-Fi switch or a NAT timeout leaves it blocked on a socket TCP will not give up on\n * for hours; the session sits thinking with nothing to report because the child never exits.\n */\nconst SSH_OPTS = [\n  \"-o\",\n  \"BatchMode=yes\",\n  \"-o\",\n  \"ConnectTimeout=10\",\n  // Errors only: at the default level a multiplexed connection ends with \"Shared connection to\n  // <host> closed.\" on stderr, which every probe reads as the box's failure text.\n  \"-o\",\n  \"LogLevel=ERROR\",\n  ...(SSH_CONTROL_DIR === undefined\n    ? []\n    : [\n        \"-o\",\n        \"ControlMaster=auto\",\n        \"-o\",\n        `ControlPath=${join(SSH_CONTROL_DIR, \"cm-%C\")}`,\n        \"-o\",\n        \"ControlPersist=60\",\n      ]),\n  \"-o\",\n  \"ServerAliveInterval=15\",\n  \"-o\",\n  \"ServerAliveCountMax=4\",\n];\n\n/** What the plugin adds to one far `claude`'s environment, beyond what every child gets. */\nexport interface FarEnv {\n  /** The box's panel login. Left out for a turn that goes to a router: the token is the Claude\n   *  account's, and an endpoint that is not Anthropic has no business holding it. */\n  token?: string | undefined;\n  /** A context window the plugin has to state (`ClaudeProcessSpec.window`). */\n  window?: number | undefined;\n}\n\n/**\n * `far` as environment pairs for the remote command line. A fresh per-box token from `claude\n * setup-token` is delivered as CLAUDE_CODE_OAUTH_TOKEN, not a stored login, so it must be handed\n * to the far claude at spawn. ponytail: it rides in the remote env argv like the rest of\n * CHILD_ENV, so it shows in the box's own `ps`; acceptable on a single-user box, tighten with a\n * remote env file if a box is shared. The window goes out under both names the CLI listens to,\n * as it does for a local spawn (`localEnvOverride`).\n */\nexport function farEnvPairs(far: FarEnv = {}): [string, string][] {\n  const pairs: [string, string][] = [];\n  if (far.token) pairs.push([\"CLAUDE_CODE_OAUTH_TOKEN\", far.token]);\n  if (far.window !== undefined)\n    pairs.push(\n      [\"CLAUDE_CODE_MAX_CONTEXT_TOKENS\", String(far.window)],\n      [\"CLAUDE_CODE_AUTO_COMPACT_WINDOW\", String(far.window)],\n    );\n  return pairs;\n}\n\n/**\n * The local `ssh` argv that runs `command args` on `host` in `cwd`. The remote shell inherits none\n * of this box's environment or working directory, so the command carries both: `cd` into `cwd`, then\n * `exec env` with CHILD_ENV (file checkpointing for rewind, the long MCP timeout). `cwd` is this\n * box's workspace path and usually does not exist on the remote, so fall back to the remote `$HOME`\n * rather than let `cd` fail the whole spawn. A remote workspace redirects `cwd` to its real remote\n * path before it reaches here (see `sshSpawner`), so that fallback is only for a plain local path.\n */\nexport function sshInvocation(\n  host: string,\n  command: string,\n  args: string[],\n  cwd: string,\n  far?: FarEnv,\n  base: NodeJS.ProcessEnv = process.env,\n) {\n  const envPairs = [...forwardedEnv(base), ...Object.entries(CHILD_ENV), ...farEnvPairs(far)];\n  const env = envPairs.map(([key, val]) => `${key}=${shq(val)}`).join(\" \");\n  const remote = [command, ...args].map(shq).join(\" \");\n  const script = `cd ${shq(cwd)} 2>/dev/null || cd \"$HOME\"; exec env ${env} ${remote}`;\n  return { command: \"ssh\", args: sshArgs(host, script) };\n}\n\n/**\n * Spawner that runs Claude Code on a remote host over SSH: this box's harness drives the far `claude`,\n * nothing runs there but the CLI itself. The stream-json wire flows through the ssh pipe unchanged, so\n * the translator, approvals and control requests are untouched. The remote uses its own `~/.claude`\n * login; the dsh MCP bridge points at this box's port and does not reach it, so `dshTools` is best off.\n */\nexport const sshSpawner =\n  (host: string, resolveCwd: (cwd: string) => string = (c) => c, far?: FarEnv): Spawner =>\n  (command, args, cwd) => {\n    const inv = sshInvocation(host, command, args, resolveCwd(cwd), far);\n    return nodeSpawner(inv.command, inv.args, \".\");\n  };\n\n/** stdin line for one user turn. `session_id` empty and `parent_tool_use_id` null match what the SDK\n *  writes. `uuid` names the line for a later `cancel_async_message`; the CLI keeps it as the message's id. */\nexport function userTurnLine(content: unknown, uuid?: string): string {\n  // Built in order, not spread: the key order is the byte order of the line, and the line without a\n  // uuid must stay what it was before the steer card.\n  const line: { type: \"user\"; uuid?: string } & Record<string, unknown> = { type: \"user\" };\n  if (uuid) line.uuid = uuid;\n  line.session_id = \"\";\n  line.message = { role: \"user\", content };\n  line.parent_tool_use_id = null;\n  return `${JSON.stringify(line)}\\n`;\n}\n\n/** stdin line answering one of the CLI's control requests with a result. */\nexport function controlResponseLine(requestId: string, response: unknown): string {\n  return `${JSON.stringify({ type: \"control_response\", response: { subtype: \"success\", request_id: requestId, response } })}\\n`;\n}\n\n/** stdin line asking the CLI to stop the current turn; it answers with a result and stays alive. */\nexport function interruptLine(requestId: string): string {\n  return `${JSON.stringify({ type: \"control_request\", request_id: requestId, request: { subtype: \"interrupt\" } })}\\n`;\n}\n\n/** A control response payload as JSON, or undefined when it is not representable. */\nexport function toJsonValue(v: unknown): JsonValue | undefined {\n  if (v === undefined) return undefined;\n  try {\n    // SAFETY: a JSON round trip yields JSON by construction\n    return JSON.parse(JSON.stringify(v)) as JsonValue;\n  } catch {\n    return undefined;\n  }\n}\n\n/** The fields of a `rewind_files` answer this plugin reports. */\nexport interface RewindResult {\n  canRewind: boolean;\n  error?: string;\n  filesChanged?: string[];\n  insertions?: number;\n  deletions?: number;\n}\n/** Whether a `cancel_async_message` reply says the CLI gave the message back. False for anything\n *  else, including a reply shape a newer CLI changed, so a doubt reads as \"already sent\". */\nexport function decodeCancelled(v: JsonValue | undefined): boolean {\n  return isRecord(v) && v.cancelled === true;\n}\n\n/** A `rewind_conversation` answer, keeping only the fields the panel shows. */\nexport function decodeRewindResult(v: JsonValue | undefined): RewindResult {\n  const r = typeof v === \"object\" && v !== null && !Array.isArray(v) ? v : {};\n  const out: RewindResult = { canRewind: r.canRewind === true };\n  if (typeof r.error === \"string\") out.error = r.error;\n  if (Array.isArray(r.filesChanged))\n    out.filesChanged = r.filesChanged.filter((f): f is string => typeof f === \"string\");\n  if (typeof r.insertions === \"number\") out.insertions = r.insertions;\n  if (typeof r.deletions === \"number\") out.deletions = r.deletions;\n  return out;\n}\n\n/**\n * A running total read as one turn's own share: the rise since the previous result, or the whole\n * figure when the total started over. `total_cost_usd` and `duration_api_ms` climb for the life of\n * a CLI process, and a new process, a resume or a mid-session `/clear` starts them\n * again from zero, which arrives here as a figure below the last one. Each result carries the\n * running total so far, so read the latest result rather than summing across results.\n */\nexport const turnDelta = (total: number, soFar: number): number =>\n  total >= soFar ? total - soFar : Math.max(0, total);\n\n/** The effort level a `get_settings` answer says is in force (`applied.effort`), or undefined when\n *  the answer has none: a model without effort levels, or a reply of another shape. */\nexport const appliedEffort = (response: JsonValue | undefined): string | undefined => {\n  const applied = isRecord(response) ? response.applied : undefined;\n  const effort = isRecord(applied) ? applied.effort : undefined;\n  return str(effort);\n};\n\n/** The true and false members of a decoded JSON object, by key; any other member, or a value that\n *  is not an object, yields none. */\nexport const flagsOf = (value: JsonValue | undefined): Array<[string, boolean]> =>\n  isRecord(value)\n    ? Object.entries(value).flatMap(([key, v]): Array<[string, boolean]> =>\n        v === true || v === false ? [[key, v]] : [],\n      )\n    : [];\n\n/** Where ultracode stands in a `get_settings` answer: whether it is in force, and whether the\n *  model in use offers it at all. Undefined for a reply of another shape. */\nexport const appliedUltracode = (\n  response: JsonValue | undefined,\n): { on: boolean; available: boolean } | undefined => {\n  const applied = isRecord(response) ? response.applied : undefined;\n  if (!isRecord(applied)) return undefined;\n  return { on: applied.ultracode === true, available: applied.ultracodeAvailable === true };\n};\n\n/** The CLI's running totals for a session: what `total_cost_usd` and `duration_api_ms` stood at. */\nexport interface RunningTotals {\n  costUsd: number;\n  apiMs: number;\n}\n\n/**\n * The totals a resumed CLI process starts counting from: the last `cost-state` row of the session's\n * transcript. The CLI writes one when a process exits and reads it back on `--resume`, so its\n * totals carry on across processes instead of starting at zero, and the first result of a new\n * process reports the whole session so far. Read as a turn's own share, that put $580.71 on one\n * turn of a session whose total had been $569.46 at the last exit (2026-10-07; 914 of 2,934\n * stored turns carried a total this way). Undefined for a transcript with no such row, where the\n * CLI starts from zero too; a row that does not parse is skipped for the one before it.\n */\nexport const costStateOf = (transcript: string): RunningTotals | undefined => {\n  for (let end = transcript.length; end > 0;) {\n    const at = transcript.lastIndexOf('\"type\":\"cost-state\"', end - 1);\n    if (at < 0) return undefined;\n    const start = transcript.lastIndexOf(\"\\n\", at) + 1;\n    const stop = transcript.indexOf(\"\\n\", at);\n    try {\n      const row: unknown = JSON.parse(transcript.slice(start, stop < 0 ? undefined : stop));\n      if (typeof row === \"object\" && row !== null) {\n        // SAFETY: a non-null object off JSON.parse; both members are checked as numbers below\n        const { totalCostUSD: cost, totalAPIDuration: api } = row as Record<string, unknown>;\n        if (typeof cost === \"number\" && typeof api === \"number\" && cost >= 0 && api >= 0)\n          return { costUsd: cost, apiMs: api };\n      }\n    } catch {\n      // A torn line: the row before it is the last one the CLI could have read back.\n    }\n    end = start;\n  }\n  return undefined;\n};\n\n/** Every `cost-state` row of a transcript that parses, in file order: the totals each process\n *  that exited left behind. Empty for a transcript with none. */\nexport const costStatesOf = (transcript: string): RunningTotals[] => {\n  const out: RunningTotals[] = [];\n  for (let at = transcript.indexOf('\"type\":\"cost-state\"'); at >= 0;) {\n    const start = transcript.lastIndexOf(\"\\n\", at) + 1;\n    const stop = transcript.indexOf(\"\\n\", at);\n    const row = costStateOf(transcript.slice(start, stop < 0 ? undefined : stop));\n    if (row) out.push(row);\n    at = stop < 0 ? -1 : transcript.indexOf('\"type\":\"cost-state\"', stop);\n  }\n  return out;\n};\n\n/** What a breakdown row is. The CLI's own words for the field: \"'used' content occupies the window;\n *  'free' is the remaining window; 'buffer' is the compaction reserve; 'deferred' rows are\n *  out-of-window tool schemas. Classify on this, never on the English name.\" Absent from a CLI\n *  older than 2.1, where the name and `isDeferred` are all there is. */\nexport type ContextRowKind = \"used\" | \"free\" | \"buffer\" | \"deferred\";\nconst ROW_KINDS: ContextRowKind[] = [\"used\", \"free\", \"buffer\", \"deferred\"];\n\n/** The slice of a `get_context_usage` answer this plugin reports: the CLI's own token count per category. */\nexport interface ContextUsage {\n  categories: Array<{ name: string; tokens: number; deferred: boolean; kind?: ContextRowKind }>;\n  totalTokens: number;\n  maxTokens: number;\n  percentage: number;\n  model?: string;\n  autocompact?: string;\n  /** Set when the CLI's window is below the plugin's table for this model while\n   *  `ANTHROPIC_BASE_URL` points off api.anthropic.com: the base URL, for the popover's notice. */\n  assumedBehind?: string;\n  /** With `assumedBehind`: the Proxy reaches Anthropic switch is on and this process predates it,\n   *  so the session's next turn replaces the process and the guess ends there. */\n  followsNext?: true;\n}\n/** Decodes a `get_context_usage` answer, returning an all-zero report when the payload is missing\n *  or not an object rather than throwing. */\nexport function decodeContextUsage(v: JsonValue | undefined): ContextUsage {\n  const r = typeof v === \"object\" && v !== null && !Array.isArray(v) ? v : {};\n  const categories: ContextUsage[\"categories\"] = [];\n  if (Array.isArray(r.categories))\n    for (const c of r.categories) {\n      if (typeof c !== \"object\" || c === null || Array.isArray(c)) continue;\n      if (typeof c.name !== \"string\" || typeof c.tokens !== \"number\") continue;\n      const row: ContextUsage[\"categories\"][number] = {\n        name: c.name,\n        tokens: c.tokens,\n        deferred: c.isDeferred === true,\n      };\n      const kind = ROW_KINDS.find((k) => k === c.kind);\n      if (kind) row.kind = kind;\n      categories.push(row);\n    }\n  const out: ContextUsage = {\n    categories,\n    totalTokens: typeof r.totalTokens === \"number\" ? r.totalTokens : 0,\n    maxTokens: typeof r.maxTokens === \"number\" ? r.maxTokens : 0,\n    percentage: typeof r.percentage === \"number\" ? r.percentage : 0,\n  };\n  if (typeof r.model === \"string\") out.model = r.model;\n  if (typeof r.autocompactSource === \"string\") out.autocompact = r.autocompactSource;\n  return out;\n}\n\n/** The text of a `get_task_output` answer: its `output` string when the CLI sent one, else the\n *  whole answer as JSON so an unexpected shape is still readable, and \"\" for nothing. */\nexport function decodeTaskOutput(v: JsonValue | undefined): string {\n  if (v === undefined || v === null) return \"\";\n  const r = typeof v === \"object\" && !Array.isArray(v) ? v : {};\n  if (typeof r.output === \"string\") return r.output;\n  return JSON.stringify(v);\n}\n\n/** The `title` of a `generate_session_title` answer, trimmed; undefined when absent or empty. */\nexport function decodeTitle(v: JsonValue | undefined): string | undefined {\n  const r = typeof v === \"object\" && v !== null && !Array.isArray(v) ? v : {};\n  const title = typeof r.title === \"string\" ? r.title.trim() : \"\";\n  return title.length > 0 ? title : undefined;\n}\n\n/** The slice of a `get_workspace_diff` answer this plugin reports. */\nexport interface WorkspaceDiff {\n  filesCount: number;\n  linesAdded: number;\n  linesRemoved: number;\n  files: Array<{\n    path: string;\n    added: number;\n    removed: number;\n    binary: boolean;\n    untracked: boolean;\n    hunks: Array<{ oldStart: number; newStart: number; lines: string[] }>;\n  }>;\n}\n/** True only for a non-null, non-array object, so a decoded CLI answer can be read by key without a\n *  guard on every field. */\nconst isRecord = (v: JsonValue | undefined): v is Record<string, JsonValue> =>\n  typeof v === \"object\" && v !== null && !Array.isArray(v);\n/** Return the number as-is, or 0 when the CLI omitted or mis-typed the field, so a missing count\n *  reads as zero rather than NaN. */\nconst num = (x: JsonValue | undefined) => (typeof x === \"number\" ? x : 0);\n/** Return the string as-is, or undefined when the CLI omitted or mis-typed the field. */\nconst str = (x: JsonValue | undefined) => (typeof x === \"string\" ? x : undefined);\n/** A `get_workspace_diff` answer as totals, per-file counts and hunks, skipping malformed entries. */\nexport function decodeWorkspaceDiff(v: JsonValue | undefined): WorkspaceDiff {\n  const outer = isRecord(v) ? v : {};\n  const d = isRecord(outer.diff) ? outer.diff : outer;\n  const stats = isRecord(d.stats) ? d.stats : {};\n  const hunksByPath = new Map<string, WorkspaceDiff[\"files\"][number][\"hunks\"]>();\n  if (Array.isArray(d.hunks))\n    for (const entry of d.hunks) {\n      if (!isRecord(entry) || typeof entry.path !== \"string\" || !Array.isArray(entry.hunks))\n        continue;\n      const list: WorkspaceDiff[\"files\"][number][\"hunks\"] = [];\n      for (const h of entry.hunks) {\n        if (!isRecord(h)) continue;\n        const lines = Array.isArray(h.lines)\n          ? h.lines.filter((l): l is string => typeof l === \"string\")\n          : [];\n        list.push({ oldStart: num(h.oldStart), newStart: num(h.newStart), lines });\n      }\n      hunksByPath.set(entry.path, list);\n    }\n  const files: WorkspaceDiff[\"files\"] = [];\n  if (Array.isArray(d.perFileStats))\n    for (const f of d.perFileStats) {\n      if (!isRecord(f) || typeof f.path !== \"string\") continue;\n      files.push({\n        path: f.path,\n        added: num(f.added),\n        removed: num(f.removed),\n        binary: f.isBinary === true,\n        untracked: f.isUntracked === true,\n        hunks: hunksByPath.get(f.path) ?? [],\n      });\n    }\n  return {\n    filesCount: num(stats.filesCount),\n    linesAdded: num(stats.linesAdded),\n    linesRemoved: num(stats.linesRemoved),\n    files,\n  };\n}\n\n/** The slice of a `list_permission_rules` answer this plugin reports. `text` is the CLI's own\n *  display line, which is why nothing here re-words a rule. */\nexport interface PermissionRules {\n  rules: Array<{ behavior: string; source: string; rule: string; text: string }>;\n  directories: Array<{ path: string; source: string }>;\n  managedOnly: boolean;\n}\n/** A `list_permission_rules` answer as rules, workspace directories and a managed-only flag,\n *  skipping malformed entries. */\nexport function decodePermissionRules(v: JsonValue | undefined): PermissionRules {\n  const outer = isRecord(v) ? v : {};\n  const state = isRecord(outer.state) ? outer.state : {};\n  const rules: PermissionRules[\"rules\"] = [];\n  if (Array.isArray(state.rules))\n    for (const r of state.rules) {\n      if (!isRecord(r)) continue;\n      const behavior = typeof r.behavior === \"string\" ? r.behavior : \"\";\n      const source = typeof r.source === \"string\" ? r.source : \"\";\n      const rule = typeof r.rule === \"string\" ? r.rule : \"\";\n      const desc = isRecord(r.description) ? r.description : {};\n      const prefix = typeof desc.prefix === \"string\" ? desc.prefix : undefined;\n      const emphasis = typeof desc.emphasis === \"string\" ? desc.emphasis : undefined;\n      const text = prefix !== undefined && emphasis !== undefined ? `${prefix} ${emphasis}` : rule;\n      rules.push({ behavior, source, rule, text });\n    }\n  const directories: PermissionRules[\"directories\"] = [];\n  if (Array.isArray(state.workspaceDirectories))\n    for (const d of state.workspaceDirectories) {\n      if (!isRecord(d) || typeof d.path !== \"string\") continue;\n      const source = typeof d.source === \"string\" ? d.source : \"\";\n      directories.push({ path: d.path, source });\n    }\n  return {\n    rules,\n    directories,\n    managedOnly: state.managedOnly === true,\n  };\n}\n\n/** The slice of a `get_hooks_listing` answer this plugin reports, one row per configured hook. */\nexport interface HooksListing {\n  hooks: Array<{ event: string; matcher: string; source: string; text: string }>;\n}\n/** A `get_hooks_listing` answer as per-hook rows, skipping malformed entries. */\nexport function decodeHooksListing(v: JsonValue | undefined): HooksListing {\n  const outer = isRecord(v) ? v : {};\n  const hooks: HooksListing[\"hooks\"] = [];\n  if (Array.isArray(outer.hooks))\n    for (const h of outer.hooks) {\n      if (!isRecord(h) || typeof h.event !== \"string\") continue;\n      const event = h.event;\n      const matcher = typeof h.matcher === \"string\" ? h.matcher : \"\";\n      const source =\n        typeof h.sourceLabel === \"string\"\n          ? h.sourceLabel\n          : typeof h.source === \"string\"\n            ? h.source\n            : \"\";\n      const text =\n        typeof h.displayText === \"string\" && h.displayText.length > 0\n          ? h.displayText\n          : typeof h.commandText === \"string\"\n            ? h.commandText\n            : \"\";\n      hooks.push({ event, matcher, source, text });\n    }\n  return { hooks };\n}\n\n/** One MCP server as `mcp_status` reports it. */\nexport interface McpServerStatus {\n  name: string;\n  status: string;\n  version?: string;\n  error?: string;\n  /** Bare tool names this server contributes. Filled from the init frame by the adapter, not by\n   *  `mcp_status`, which does not report tools; absent when no init frame has been seen. */\n  tools?: string[];\n  /** This server's tools have been pinned back to asking on the live process. The adapter's own\n   *  record, not the CLI's: `mcp_status` reports connection and nothing about permissions. */\n  asking?: boolean;\n}\n/** An `mcp_status` answer as one row per server, with its own error kept when it is not connected. */\nexport function decodeMcpStatus(v: JsonValue | undefined): McpServerStatus[] {\n  const r = isRecord(v) ? v : {};\n  const out: McpServerStatus[] = [];\n  if (Array.isArray(r.mcpServers))\n    for (const m of r.mcpServers) {\n      if (!isRecord(m) || typeof m.name !== \"string\") continue;\n      const entry: McpServerStatus = {\n        name: m.name,\n        status: typeof m.status === \"string\" ? m.status : \"unknown\",\n      };\n      const info = isRecord(m.serverInfo) ? m.serverInfo : {};\n      if (typeof info.version === \"string\") entry.version = info.version;\n      // SAFETY: defensive typeof checks match I/O boundary style; keep error or message if present\n      if (typeof m.error === \"string\") {\n        entry.error = m.error;\n      } else if (typeof m.message === \"string\") {\n        entry.error = m.message;\n      }\n      out.push(entry);\n    }\n  return out;\n}\n\n/** The sign-in page from an `mcp_authenticate` reply, or undefined when the reply does not carry\n *  one. Probed against 2.1.278 on 2026-09-20. */\nexport function mcpAuthUrl(v: JsonValue | undefined): string | undefined {\n  const r = isRecord(v) ? v : {};\n  return typeof r.authUrl === \"string\" && r.authUrl !== \"\" ? r.authUrl : undefined;\n}\n\n/** True when the CLI answered success with nothing for the person to do: the server's token is\n *  still good, so there is no page to open. Distinguishing this from a failure matters, because the\n *  panel would otherwise tell someone their login failed when they are already signed in. */\nexport function mcpAuthNeedsNothing(v: JsonValue | undefined): boolean {\n  const r = isRecord(v) ? v : {};\n  return r.requiresUserAction === false;\n}\n\n/** One entry of the CLI's own model picker, as `list_models` reports it. */\nexport interface CliModel {\n  value: string;\n  resolvedModel: string;\n  displayName: string;\n  /** The CLI picker's one-line blurb (\"Opus 5 with 1M context · Best for everyday, complex tasks\"). */\n  description?: string;\n  efforts: string[];\n}\n/** A `list_models` answer: what `claude --model` accepts for this login, aliases included. */\nexport function decodeCliModels(v: JsonValue | undefined): CliModel[] {\n  const r = isRecord(v) ? v : {};\n  const out: CliModel[] = [];\n  if (Array.isArray(r.models))\n    for (const m of r.models) {\n      if (!isRecord(m) || typeof m.value !== \"string\") continue;\n      const row: CliModel = {\n        value: m.value,\n        resolvedModel: typeof m.resolvedModel === \"string\" ? m.resolvedModel : m.value,\n        displayName: typeof m.displayName === \"string\" ? m.displayName : m.value,\n        // The CLI answers `supportedEffortLevels`; the on-disk seed (`cli-models.json`) holds this\n        // row shape back, keyed `efforts`. Read both, or a restart seeds every row with no efforts\n        // and dsh refuses the effort a session still carries (2026-09-18).\n        efforts: (Array.isArray(m.supportedEffortLevels)\n          ? m.supportedEffortLevels\n          : Array.isArray(m.efforts)\n            ? m.efforts\n            : []\n        ).filter((e): e is string => typeof e === \"string\"),\n      };\n      if (typeof m.description === \"string\") row.description = m.description;\n      out.push(row);\n    }\n  return out;\n}\n\n/** The request fields of an `elicitation` control request this plugin reads. */\nexport interface ElicitationRequest {\n  mcp_server_name?: string;\n  display_name?: string;\n  message?: string;\n  mode?: string;\n  url?: string;\n  requested_schema?: JsonValue;\n}\ntype SchemaProp = {\n  key: string;\n  type: string;\n  enum?: string[];\n  title?: string;\n  description?: string;\n};\n/** Pull a schema's top-level properties out of an MCP elicitation request, or undefined when it has\n *  no usable properties or more than 20. */\nfunction schemaProps(schema: JsonValue | undefined): SchemaProp[] | undefined {\n  const s = isRecord(schema) ? schema : {};\n  const props = isRecord(s.properties) ? s.properties : undefined;\n  if (!props) return undefined;\n  const out: SchemaProp[] = [];\n  for (const [key, def] of Object.entries(props)) {\n    if (!isRecord(def)) return undefined;\n    const type = typeof def.type === \"string\" ? def.type : \"string\";\n    const prop: SchemaProp = { key, type };\n    if (Array.isArray(def.enum)) prop.enum = def.enum.map((e) => String(e));\n    if (typeof def.title === \"string\") prop.title = def.title;\n    if (typeof def.description === \"string\") prop.description = def.description;\n    out.push(prop);\n  }\n  return out.length > 0 && out.length <= 20 ? out : undefined;\n}\n/**\n * An MCP elicitation as dsh questions: one per top-level schema property. Enum and boolean\n * properties become choices, strings and numbers a custom answer. Undefined when the schema has\n * no usable properties, or the mode is not a form.\n */\nexport function elicitationQuestions(\n  request: ElicitationRequest,\n  requestId: string,\n): AskUserQuestionItem[] | undefined {\n  if (request.mode === \"url\") return undefined;\n  const props = schemaProps(request.requested_schema);\n  if (!props) return undefined;\n  const header = request.display_name ?? request.mcp_server_name ?? \"MCP server\";\n  return props.map((p, index) => {\n    const item: AskUserQuestionItem = {\n      id: `${requestId}:${p.key}`,\n      header,\n      question: p.title ?? p.description ?? p.key,\n      options:\n        p.type === \"boolean\"\n          ? [{ label: \"Yes\" }, { label: \"No\" }]\n          : (p.enum ?? []).map((label) => ({ label })),\n      multiSelect: false,\n    };\n    if (index === 0 && request.message) item.detail = request.message;\n    return item;\n  });\n}\n/** dsh's answers → the elicitation result the CLI relays: accept with content, or cancel. */\nexport function elicitationResult(\n  request: ElicitationRequest,\n  response: { answers?: Array<{ id: string; custom?: string; selected?: string[] }> },\n  requestId: string,\n): Record<string, JsonValue> {\n  const props = schemaProps(request.requested_schema) ?? [];\n  const byId = new Map((response?.answers ?? []).map((a) => [a.id, a]));\n  const content: Record<string, JsonValue> = {};\n  for (const p of props) {\n    const a = byId.get(`${requestId}:${p.key}`);\n    const raw = (typeof a?.custom === \"string\" && a.custom) || a?.selected?.[0] || \"\";\n    if (raw === \"\") continue;\n    if (p.type === \"boolean\") content[p.key] = raw === \"Yes\";\n    else if (p.type === \"number\" || p.type === \"integer\") {\n      const n = Number(raw);\n      if (Number.isFinite(n)) content[p.key] = n;\n    } else content[p.key] = raw;\n  }\n  return Object.keys(content).length > 0 ? { action: \"accept\", content } : { action: \"cancel\" };\n}\n\n/** True for a `result` frame of any outcome; anything unparsable or of another type is false. */\nexport function isResultLine(line: string): boolean {\n  try {\n    const parsed: unknown = JSON.parse(line);\n    // SAFETY: a non-null object compared to one literal, never trusted as typed\n    return (\n      typeof parsed === \"object\" &&\n      parsed !== null &&\n      (parsed as { type?: unknown }).type === \"result\"\n    );\n  } catch {\n    return false;\n  }\n}\n\n/** True for the CLI's `background_tasks_changed` frame, the snapshot of its live background tasks;\n *  a tool's text that merely mentions the name is another frame type and is false. */\nexport function isBackgroundTasksFrame(line: string): boolean {\n  try {\n    const parsed: unknown = JSON.parse(line);\n    // SAFETY: a non-null object; each field is compared to a literal, never trusted as typed\n    const r = parsed as { type?: unknown; subtype?: unknown };\n    return (\n      typeof parsed === \"object\" &&\n      parsed !== null &&\n      r.type === \"system\" &&\n      r.subtype === \"background_tasks_changed\"\n    );\n  } catch {\n    return false;\n  }\n}\n\n/**\n * A `result` line that arrived while no turn was reading, and that is worth a wake: a completed\n * reply. An error result is not: on a rate limit the CLI retries on its own and emits one error\n * result per attempt, and waking on each opened a rejected turn every 73 s until the limit reset\n * (2026-09-06 22:51 to 23:00, eight turns).\n */\nexport function isIdleReply(line: string): boolean {\n  try {\n    const parsed: unknown = JSON.parse(line);\n    if (typeof parsed !== \"object\" || parsed === null) return false;\n    // SAFETY: a non-null object; each field is compared to a literal, never trusted as typed\n    const r = parsed as { type?: unknown; is_error?: unknown; subtype?: unknown };\n    return r.type === \"result\" && r.is_error !== true && r.subtype !== \"error_during_execution\";\n  } catch {\n    return false; // not JSON: nextEvent() files it under `stray`\n  }\n}\n\n/** stdin line for any control request this plugin sends; the CLI answers with a `control_response`. */\nexport function controlRequestLine(requestId: string, request: Record<string, JsonValue>): string {\n  return `${JSON.stringify({ type: \"control_request\", request_id: requestId, request })}\\n`;\n}\n\n/** stdin line answering one of the CLI's control requests with a failure. */\nexport function controlErrorLine(requestId: string, error: unknown): string {\n  return `${JSON.stringify({ type: \"control_response\", response: { subtype: \"error\", request_id: requestId, error } })}\\n`;\n}\n\n/** Lets a tool call run, with the input dsh approved, which may differ from the one asked for. */\nexport const allowResult = (toolUseId: string, input: unknown) => ({\n  behavior: \"allow\" as const,\n  updatedInput: input,\n  toolUseID: toolUseId,\n  decisionClassification: \"user_temporary\" as const,\n});\n\n/** Refuses a tool call and tells Claude why; the CLI reads this as the user rejecting it. */\nexport const denyResult = (toolUseId: string, message: string) => ({\n  behavior: \"deny\" as const,\n  message,\n  toolUseID: toolUseId,\n  decisionClassification: \"user_reject\" as const,\n});\n\n/** Claude's AskUserQuestion input → dsh question items. Undefined when the shape is not what the tool documents. */\nexport function parseQuestions(\n  input: Record<string, unknown>,\n  toolUseId: string,\n): AskUserQuestionItem[] | undefined {\n  const list = input?.questions;\n  if (!Array.isArray(list) || list.length === 0 || list.length > 20) return undefined;\n  const out: AskUserQuestionItem[] = [];\n  for (const [index, item] of list.entries()) {\n    if (!item || typeof item !== \"object\" || typeof item.question !== \"string\" || !item.question)\n      return undefined;\n    const options: AskUserQuestionItem[\"options\"] = [];\n    // dsh's option has a label and a description only; a preview (a mockup, a snippet) rides\n    // under the question as `detail`, one fenced block per option, four backticks so a preview\n    // that holds a fence of its own survives.\n    const previews: string[] = [];\n    for (const o of Array.isArray(item.options) ? item.options : []) {\n      if (!o || typeof o.label !== \"string\" || !o.label) return undefined;\n      const optObj: AskUserQuestionItem[\"options\"][number] = {\n        label: o.label,\n      };\n      if (typeof o.description === \"string\" && o.description) optObj.description = o.description;\n      options.push(optObj);\n      if (typeof o.preview === \"string\" && o.preview.trim() !== \"\")\n        previews.push(`**${o.label}**\\n\\n\\`\\`\\`\\`\\n${o.preview.trim()}\\n\\`\\`\\`\\``);\n    }\n    const outItem: AskUserQuestionItem = {\n      id: `${toolUseId}:${index}`,\n      question: item.question,\n      options,\n      multiSelect: item.multiSelect === true,\n    };\n    if (typeof item.header === \"string\" && item.header) outItem.header = item.header;\n    if (previews.length > 0) outItem.detail = previews.join(\"\\n\\n\");\n    out.push(outItem);\n  }\n  return out;\n}\n\n/** dsh answers → the `answers` map Claude expects back in updatedInput, keyed by question text. */\nexport function answersFor(\n  questions: Array<{ id: string; question: string; multiSelect?: boolean }>,\n  response: { answers?: Array<{ id: string; custom?: string; selected?: string[] }> },\n) {\n  const byId = new Map((response?.answers ?? []).map((a) => [a.id, a]));\n  const answers: Record<string, string> = {};\n  for (const q of questions) {\n    const a = byId.get(q.id);\n    const custom = typeof a?.custom === \"string\" && a.custom ? a.custom : undefined;\n    if (!a) answers[q.question] = \"\";\n    else if (!q.multiSelect && custom) answers[q.question] = custom;\n    else answers[q.question] = [...(a.selected ?? []), ...(custom ? [custom] : [])].join(\", \");\n  }\n  return answers;\n}\n\n/** One-line human reason for the approval dialog. */\nexport function permissionReason(\n  toolName: string,\n  input: Record<string, unknown>,\n  request: Record<string, unknown>,\n): string {\n  const head = request?.title ?? request?.description ?? \"\";\n  let detail = \"\";\n  // Any tool that runs a command line (`Bash`, and `PowerShell` on Windows) shows the command.\n  if (typeof input?.command === \"string\") detail = input.command;\n  else if (typeof input?.file_path === \"string\") detail = input.file_path;\n  else if (typeof input?.url === \"string\") detail = input.url;\n  else if (input && typeof input === \"object\") detail = JSON.stringify(input);\n  const text = [head, detail].filter(Boolean).join(\": \");\n  return text.length > 400 ? `${text.slice(0, 400)}…` : text || toolName;\n}\n\n/** Returned by `next(timeoutMs)` when nothing arrived in time; the waiter is withdrawn, no line is lost. */\nexport const TIMEOUT = Symbol(\"timeout\");\n\n/** Async line queue over a child's stdout: `next()` resolves with the next line, or null once the child is gone. */\nexport class LineQueue {\n  lines: (string | ClaudeEvent | Record<string, unknown>)[];\n  waiters: Array<(line: string | typeof TIMEOUT | null) => void>;\n  closed: boolean;\n\n  /** Start with no queued lines, no waiters and no close flag; every field stays empty until the\n   *  first push. */\n  constructor() {\n    this.lines = [];\n    this.waiters = [];\n    this.closed = false;\n  }\n  /** Hand a line to the earliest waiter if one is waiting, else buffer it, so a line never arrives\n   *  before its reader. */\n  push(line: string | ClaudeEvent | Record<string, unknown>) {\n    const w = this.waiters.shift();\n    if (w && line !== null) {\n      // SAFETY: TIMEOUT is never pushed; only strings or parsed objects reach here\n      w(line as string);\n    } else {\n      this.lines.push(line);\n    }\n  }\n  /** Mark the queue closed and resolve every pending waiter with null, so a stopped child's\n   *  readers see the end. */\n  close() {\n    this.closed = true;\n    for (const w of this.waiters.splice(0)) w(null);\n  }\n  /** Resolve with the next queued line, a timeout after `timeoutMs` with nothing, or null once the\n   *  queue is closed. */\n  next(timeoutMs?: number): Promise<string | typeof TIMEOUT | null> {\n    if (this.lines.length > 0) {\n      const line = this.lines.shift();\n      // SAFETY: TIMEOUT sentinel is never stored in lines; only strings or objects arrive here\n      return Promise.resolve((line ?? null) as string | typeof TIMEOUT | null);\n    }\n    if (this.closed) return Promise.resolve(null);\n    return new Promise((resolve) => {\n      const waiter = (line: string | typeof TIMEOUT | null) => {\n        clearTimeout(timer);\n        resolve(line);\n      };\n      const timer =\n        timeoutMs === undefined\n          ? undefined\n          : setTimeout(() => {\n              const i = this.waiters.indexOf(waiter);\n              if (i >= 0) this.waiters.splice(i, 1);\n              resolve(TIMEOUT);\n            }, timeoutMs);\n      this.waiters.push(waiter);\n    });\n  }\n}\n\n/** Everything one turn needs, as `prepare()` returns it; the process keeps the last one. */\nexport interface TurnPrep {\n  cwd: string;\n  args: string[];\n  session?: { id: string; resuming: boolean };\n  spec: ClaudeProcessSpec;\n  accessMode?: string;\n  input: string | null;\n  /** The context blocks the Settings switches withhold, read once when this turn was assembled. */\n  drops?: ReadonlySet<ContextSource>;\n  /** What each of those blocks cost this turn in characters, before any of them were withheld.\n   *  Absent on a side call, which has no workspace to record a number against. */\n  sizes?: ContextSizes;\n  /** Set when this turn's key comes from a settings file's `env`, not from the Claude login:\n   *  see `ClaudeCodeAdapter.settingsKey`. */\n  settingsKey?: SettingsKey;\n  /** The host this turn's requests go to when it is not Anthropic and does not forward there:\n   *  see `TurnRecord.via`. */\n  via?: string;\n}\n\n/** Where a turn's request goes when its key was set by a settings file, and, when the address\n *  and the key were set by two different files, a sentence saying which. */\nexport interface SettingsKey {\n  host: string;\n  split?: string;\n}\n\n/** Everything a Claude process needs at spawn: where it runs, how it is reached, what it may do. */\nexport interface ClaudeProcessSpec {\n  cwd: string;\n  model: string | undefined;\n  effort: string | null;\n  mode: string;\n  sessionId: string | null;\n  /** Launched with --no-session-persistence: Claude keeps no transcript for this session. */\n  temporary: boolean;\n  /** Spawned with the CLI's \"the proxy is Anthropic\" flag (the Proxy reaches Anthropic switch).\n   *  Present only when on, so a spec saved before the switch existed still keys the same; a flip\n   *  changes the key, and the session's next turn replaces the process, as an effort change does. */\n  firstParty?: true;\n  /** The base URL a settings file gave the CLI at spawn, when it is not the one dsh itself was\n   *  started with: a router switched on in settings.json. Absent otherwise, so every spec saved\n   *  before the field existed keys the same. A process reads its environment once, so a router\n   *  switched on or off under a running session changes the key and the session's next turn\n   *  replaces the process; without that it would go on talking to wherever it was started for. */\n  route?: string;\n  /** The turn was proven to go to a router (`TurnPrep.via`), so the process is started without\n   *  the Claude account's panel login in its environment. On the spec, like `firstParty`, so the\n   *  environment and the key that names the process are one decision: a flag on the adapter could\n   *  be flipped by another session's `prepare` between the two. Present only when on. */\n  routed?: true;\n  /** The context window the CLI was told to run this model with (`CLAUDE_CODE_MAX_CONTEXT_TOKENS`\n   *  and `CLAUDE_CODE_AUTO_COMPACT_WINDOW` at spawn), for a row whose window is the plugin's or\n   *  the user's to say: a router's alias, an added model with a stated size. Absent otherwise, so\n   *  every other spec keys as before; a size changed in Settings changes the key and the\n   *  session's next turn starts a process that knows it. */\n  window?: number;\n  /** Started as dsh's child rather than under a keeper: the Settings switch off, or `spawn: node` or\n   *  `dsh` in the config. Absent for a keeper, so a keeper's saved spec keys the same as it did\n   *  before the field existed; a flip changes the key and the session's next turn respawns, never\n   *  the turn in flight. */\n  child?: \"node\" | \"dsh\";\n}\n\n/** What the caller wants to know when a Claude process ends, live or after a restart. */\nexport interface ClaudeProcessOnExit {\n  (proc: ClaudeProcess): void;\n}\n\n/** The stream-json frame types that only come out of a turn Claude is running; a queued one is a\n *  reply nobody has seen yet. `control_request` is the CLI asking something a turn has to answer\n *  (a permission, a dsh tool call). `tool_progress` comes every 30 s while a tool runs (probed on\n *  2.1.318 with a 100 s Bash), so an adopted session mid-tool gets its reattached notice within\n *  30 s, as before the allow list; the output itself is drawn when the turn's result wakes it. */\nconst TURN_FRAMES = new Set([\n  \"assistant\",\n  \"user\",\n  \"result\",\n  \"stream_event\",\n  \"control_request\",\n  \"tool_progress\",\n]);\n\n/** The same frames found by text, for the line handler's cheap \"Claude is working\" check; a match\n *  inside a tool's own text only delays the idle reaper. */\nconst TURN_FRAME_TEXT =\n  /\"type\":\"(?:assistant|user|result|stream_event|control_request|tool_progress)\"/;\n\n/** Where a keeper lives: its socket, spec, info and the Claude process it owns. */\nexport interface KeeperPaths {\n  dir: string;\n  sock: string;\n  spec: string;\n  info: string;\n}\n/** The keeper's socket, spec and info files, all one level under the keeper's directory. */\nconst keeperPaths = (dir: string): KeeperPaths => ({\n  dir,\n  sock: join(dir, \"keeper.sock\"),\n  spec: join(dir, \"spec.json\"),\n  info: join(dir, \"keeper.json\"),\n});\n\n/** What `keeper.json` says about a keeper; `exit` is set once Claude has left. */\nexport interface KeeperInfo {\n  pid: number;\n  claudePid: number;\n  sessionId: string;\n  startedAt: number;\n  exit: {\n    code: number | null;\n    signal: string | null;\n  } | null;\n  /** Who ended Claude: a kill message from dsh, Claude itself, the keeper crashing, or the keeper's\n   *  orphan timer (nobody attached for orphanMs); null while it runs. */\n  endedBy: \"client\" | \"child\" | \"keeper-crash\" | \"orphan\" | null;\n}\n\n/** The keeper record in a spawn directory, or undefined when it is missing or damaged. */\nexport function readKeeperInfo(dir: string): KeeperInfo | undefined {\n  try {\n    const parsed: unknown = JSON.parse(readFileSync(keeperPaths(dir).info, \"utf8\"));\n    if (typeof parsed !== \"object\" || parsed === null) return undefined;\n    // SAFETY: keeper.json is written by keeper.ts from a typed object; each field is re-checked below\n    const p = parsed as Partial<KeeperInfo>;\n    if (typeof p.pid !== \"number\" || typeof p.sessionId !== \"string\") return undefined;\n    return {\n      pid: p.pid,\n      claudePid: typeof p.claudePid === \"number\" ? p.claudePid : -1,\n      sessionId: p.sessionId,\n      startedAt: typeof p.startedAt === \"number\" ? p.startedAt : 0,\n      exit: p.exit ?? null,\n      endedBy:\n        p.endedBy === \"client\" ||\n        p.endedBy === \"child\" ||\n        p.endedBy === \"keeper-crash\" ||\n        p.endedBy === \"orphan\"\n          ? p.endedBy\n          : null,\n    };\n  } catch {\n    return undefined;\n  }\n}\n\n/** True when a pid is alive (signal 0). Only a positive pid is one process: `kill(0, …)` is the\n *  caller's own process group and `kill(-1, …)` is every process this user owns, so a record that\n *  lost its pid (a keeper whose spawn failed writes none, read back as -1) must answer \"not\n *  alive\" here, or the orphan kill that follows sends SIGTERM to the user's whole login session\n *  (2026-09-17: a dsh-web restart logged the owner out of the desktop). */\nexport const pidAlive = (pid: number): boolean => {\n  if (!Number.isInteger(pid) || pid <= 0) return false;\n  try {\n    process.kill(pid, 0);\n    return true;\n  } catch {\n    return false;\n  }\n};\n\n/**\n * Attach to a keeper's socket and present it as a SubprocessHandle: stdin lines become `in`\n * messages, `out`/`err` lines feed the readable sides, `exit` settles `done`, terminate sends\n * `kill`. Rejects when the socket does not answer within `timeoutMs`.\n */\nexport function attachKeeper(dir: string, timeoutMs = 5000): Promise<SubprocessHandle> {\n  const paths = keeperPaths(dir);\n  return new Promise((resolve, reject) => {\n    const started = Date.now();\n    const tryConnect = () => {\n      const sock = connect(paths.sock);\n      sock.once(\"error\", () => {\n        if (Date.now() - started > timeoutMs) reject(new Error(`keeper at ${dir} did not answer`));\n        else setTimeout(tryConnect, 150);\n      });\n      sock.once(\"connect\", () => {\n        sock.removeAllListeners(\"error\");\n        sock.on(\"error\", () => {});\n        const stdout = new PassThrough();\n        const stderr = new PassThrough();\n        let resolveDone:\n          | ((v: { exitCode: number | null; signal: string | null }) => void)\n          | undefined;\n        const done = new Promise<{ exitCode: number | null; signal: string | null }>((r) => {\n          resolveDone = r;\n        });\n        let settled = false;\n        // The keeper's number for each stdout line, by its index on this handle, until acked.\n        const numbers = new Map<number, number>();\n        let lineIndex = 0;\n        const settle = (code: number | null, signal: string | null) => {\n          if (settled) return;\n          settled = true;\n          stdout.end();\n          stderr.end();\n          resolveDone?.({ exitCode: code, signal });\n        };\n        createInterface({ input: sock, crlfDelay: Infinity }).on(\"line\", (raw) => {\n          let msg: {\n            t?: string;\n            line?: string;\n            n?: number;\n            code?: number | null;\n            signal?: string | null;\n          };\n          try {\n            // SAFETY: the peer is this plugin's keeper.ts; fields are checked before use\n            msg = JSON.parse(raw) as typeof msg;\n          } catch {\n            return;\n          }\n          if (msg.t === \"out\" && typeof msg.line === \"string\") {\n            // A keeper from before acks sends no number; its lines are not kept, so nothing is acked.\n            if (typeof msg.n === \"number\") numbers.set(lineIndex, msg.n);\n            lineIndex++;\n            stdout.write(`${msg.line}\\n`);\n          } else if (msg.t === \"err\" && typeof msg.line === \"string\") stderr.write(`${msg.line}\\n`);\n          else if (msg.t === \"exit\") settle(msg.code ?? null, msg.signal ?? null);\n        });\n        // A closed socket with no `exit` first means the keeper is gone (crashed, or another dsh\n        // took the connection); either way this handle's process is over for us.\n        sock.on(\"close\", () => settle(-1, \"socket-closed\"));\n        const stdin = new Writable({\n          write(chunk, _enc, cb) {\n            const text = String(chunk);\n            for (const line of text.split(\"\\n\"))\n              if (line !== \"\") sock.write(`${JSON.stringify({ t: \"in\", line: `${line}\\n` })}\\n`);\n            cb();\n          },\n        });\n        sock.write(`${JSON.stringify({ t: \"hello\", acks: true })}\\n`);\n        resolve({\n          stdin,\n          stdout,\n          stderr,\n          done,\n          terminate: () => {\n            sock.write(`${JSON.stringify({ t: \"kill\" })}\\n`);\n          },\n          ack: (index) => {\n            const n = numbers.get(index);\n            if (n === undefined) return;\n            numbers.delete(index);\n            if (!sock.destroyed) sock.write(`${JSON.stringify({ t: \"ack\", n })}\\n`);\n          },\n        });\n      });\n    };\n    tryConnect();\n  });\n}\n\n/**\n * A SubprocessHandle that is usable at once while the real one is still being attached: stdin\n * writes queue until then, stdout/stderr are piped through, done and terminate follow the real one.\n */\nexport function lazyHandle(pending: Promise<SubprocessHandle>): SubprocessHandle {\n  const stdout = new PassThrough();\n  const stderr = new PassThrough();\n  const queued: string[] = [];\n  let real: SubprocessHandle | undefined;\n  let killed = false;\n  const settled = pending.then(\n    (h) => {\n      real = h;\n      h.stdout.pipe(stdout);\n      h.stderr.pipe(stderr);\n      for (const line of queued) h.stdin.write(line);\n      queued.length = 0;\n      if (killed) h.terminate();\n      return h.done;\n    },\n    (error: Error) => {\n      stderr.write(`keeper: ${error.message}\\n`);\n      stdout.end();\n      stderr.end();\n      return { exitCode: -1, signal: null };\n    },\n  );\n  const stdin = new Writable({\n    write(chunk, _enc, cb) {\n      if (real) real.stdin.write(String(chunk));\n      else queued.push(String(chunk));\n      cb();\n    },\n  });\n  return {\n    stdin,\n    stdout,\n    stderr,\n    done: settled,\n    terminate: () => {\n      killed = true;\n      real?.terminate();\n    },\n    // stdout is the real handle's piped through, so its line indexes are the real one's.\n    ack: (index) => real?.ack?.(index),\n  };\n}\n\n/** The keeper's record of the process it babysits, written at spawn and read after a restart. */\nexport interface KeeperSpec {\n  command: string;\n  args: string[];\n  cwd: string;\n  env: Record<string, string>;\n  sessionId: string;\n  /** The adapter's process spec, so an adopted keeper matches the next request's spec. */\n  procSpec?: ClaudeProcessSpec;\n  /** The dsh that started it (spawn-mode.ts `keeperOwner`); another dsh on the box leaves it alone. */\n  owner?: string;\n  /** keeper.ts ends Claude after this long with no dsh attached and no output; absent, never. */\n  orphanMs?: number;\n}\n\n/** The spawn arguments a keeper was started with, for adopting or respawning it after a restart. */\nexport function readKeeperSpec(dir: string): KeeperSpec | undefined {\n  try {\n    const parsed: unknown = JSON.parse(readFileSync(keeperPaths(dir).spec, \"utf8\"));\n    if (typeof parsed !== \"object\" || parsed === null) return undefined;\n    // SAFETY: spec.json is written by spawnKeeper from a KeeperSpec; the fields that matter are re-checked\n    const s = parsed as KeeperSpec;\n    if (typeof s.command !== \"string\" || !Array.isArray(s.args) || typeof s.sessionId !== \"string\")\n      return undefined;\n    return s;\n  } catch {\n    return undefined;\n  }\n}\n\n/** Launch the keeper in its own systemd user scope when possible (a service restart's cgroup kill\n *  then misses it), else as a detached process with its own group. */\nexport function launchKeeper(argv: string[], unit: string): void {\n  /** Launch the keeper fully detached with stdio discarded, so it survives the parent that started\n   *  it. */\n  const detached = () => {\n    const c = spawn(argv[0] ?? process.execPath, argv.slice(1), {\n      detached: true,\n      stdio: \"ignore\",\n    });\n    c.unref();\n  };\n  try {\n    const started = Date.now();\n    const c = spawn(\n      \"systemd-run\",\n      [\"--user\", \"--scope\", \"--quiet\", \"--collect\", `--unit=${unit}`, ...argv],\n      { detached: true, stdio: \"ignore\" },\n    );\n    c.on(\"error\", detached);\n    // With --scope, systemd-run runs the keeper itself and lives as long as it does. One that exits\n    // with an error straight away never started it: it is installed but cannot reach the user bus\n    // (a container, WSL, an SSH login with no user manager, a launcher that clears the environment)\n    // and printed \"Failed to connect to bus\". The spawn succeeded, so `error` never fires; without\n    // this every turn died as \"keeper did not answer\" (found 2026-09-21 running dsh under Electron\n    // with a cleared environment). Decided on exit, not by a probe up front, so nothing blocks.\n    c.on(\"exit\", (code) => {\n      if (scopeFailed(code, Date.now() - started)) detached();\n    });\n    c.unref();\n  } catch {\n    detached();\n  }\n}\n\n/** Whether a `systemd-run --scope` that exited with `code` after `elapsedMs` failed to start the\n *  keeper rather than outliving it. A keeper stays up at least three seconds after its Claude dies,\n *  so a non-zero exit inside two seconds is systemd-run refusing, not the keeper ending. */\nexport function scopeFailed(code: number | null, elapsedMs: number): boolean {\n  return code !== 0 && code !== null && elapsedMs < 2000;\n}\n\n/**\n * Start a keeper for one Claude process and attach to it. `launch` runs the keeper command line\n * (plain detached spawn, or a systemd user scope so a service restart's cgroup kill misses it).\n */\nexport async function spawnKeeper(\n  dir: string,\n  spec: KeeperSpec,\n  launch: (argv: string[]) => void,\n): Promise<SubprocessHandle> {\n  const paths = keeperPaths(dir);\n  // Owner-only: the spec holds the child's whole environment, a login token and the bridge key\n  // among it, and the socket beside it takes stdin lines from whoever can open it.\n  mkdirSync(dir, { recursive: true, mode: 0o700 });\n  writeFileSync(paths.spec, JSON.stringify(spec), { mode: 0o600 });\n  // A respawn reuses the session's directory while the previous keeper still listens for up to\n  // 3 s after its Claude died. Left in place, that socket is what attachKeeper connects to first,\n  // binding the new handle to the dying process (2026-09-06 21:27: \"claude exited 143\" on a model\n  // switch, and the fresh Claude orphaned). Unlink it so only the new keeper can answer.\n  try {\n    unlinkSync(paths.sock);\n  } catch {\n    // no stale socket\n  }\n  // fileURLToPath, not `.pathname`: the pathname keeps %20 for a space and a leading slash before a\n  // Windows drive letter, so the keeper script is not found under either.\n  const keeperJs = fileURLToPath(new URL(\"./keeper.js\", import.meta.url));\n  launch([process.execPath, keeperJs, dir]);\n  return attachKeeper(dir, 8000);\n}\n\n/** How a child is started: locally, or on a box over ssh. The adapter holds one per provider. */\nexport type Spawner = (\n  command: string,\n  args: string[],\n  cwd: string,\n  envOverride?: Record<string, string>,\n) => SubprocessHandle;\n\n/** What the steer card shows of a message's file or image: enough to name it, never its bytes. */\nexport type SteerAttachment = { kind: \"file\" | \"image\"; name?: string; bytes: number };\n\n/** A typed steer Claude has not read yet, keyed by its dsh message id in `steers`. Three kinds:\n *  written to stdin during a native tool (has the line's `uuid`, and `cancel_async_message`\n *  takes it back); left in dsh's inbox during a dsh tool (`relayed`, never written, so there is\n *  nothing to cancel; dsh staples it to the relay result at the tool's end); or left in dsh's inbox\n *  during a native tool because it carries a file or image, which stdin cannot take (`boundary`:\n *  counted in `forwarded`, it parks the step at the next tool result, where dsh delivers it\n *  whole). */\nexport type WaitingSteer = {\n  /** Its steerKey, the entry in the process's `sent` set (never added for a steer dsh holds). */\n  key: string;\n  /** What Claude will read: the latest edit. Empty for a message that is only a file or image. */\n  text: string;\n  /** Epoch ms of the first record, for ordering. */\n  at: number;\n  /** Present only when the message carries a file or image. */\n  attachments?: SteerAttachment[];\n} & (\n  | {\n      /** The stdin line's uuid, which `cancel_async_message` names. */\n      uuid: string;\n      relayed?: false;\n      boundary?: false;\n    }\n  | {\n      uuid?: undefined;\n      /** Waiting in dsh's inbox while the CLI is inside a dsh tool. */\n      relayed: true;\n      boundary?: false;\n    }\n  | {\n      uuid?: undefined;\n      relayed?: false;\n      /** Waiting in dsh's inbox for the next tool result, since its file or image cannot go over\n       *  stdin. Named apart from `ClaudeProcess.parked`, the step's own state. */\n      boundary: true;\n    }\n);\n\n/**\n * The permission mode a CLI stdout line reports, else undefined. The CLI writes\n * `{\"type\":\"system\",\"subtype\":\"status\",\"permissionMode\":…}` whenever its mode changes, including a\n * change it makes itself (EnterPlanMode, an approved ExitPlanMode), the only way the plugin learns\n * of those (CLI 2.1.322). The `init` frame that opens every turn names the mode the CLI is in at\n * that moment too (probed on 2.1.322: switched to plan between two turns, the second turn's init\n * said plan). That one matters after a dsh restart: the kept process is adopted with the mode it\n * was launched in, and until its mode next changed the plan-mode gate read the wrong one. Lines\n * without the key are not parsed, so the hot path stays cheap.\n */\nexport function statusMode(line: string): string | undefined {\n  if (!line.includes('\"permissionMode\"')) return undefined;\n  if (!line.includes('\"status\"') && !line.includes('\"init\"')) return undefined;\n  let parsed: unknown;\n  try {\n    parsed = JSON.parse(line);\n  } catch {\n    return undefined;\n  }\n  if (typeof parsed !== \"object\" || parsed === null) return undefined;\n  // SAFETY: a non-null object; each field is compared to a literal or type-checked before use\n  const r = parsed as { type?: unknown; subtype?: unknown; permissionMode?: unknown };\n  if (r.type !== \"system\" || (r.subtype !== \"status\" && r.subtype !== \"init\")) return undefined;\n  return typeof r.permissionMode === \"string\" ? r.permissionMode : undefined;\n}\n\n/**\n * A running Claude Code process bound to one dsh session. `spec` is what the process was spawned\n * with (cwd, model, effort, permission mode, session flags); a turn whose spec differs replaces it.\n */\nexport class ClaudeProcess {\n  spec: ClaudeProcessSpec;\n  /** The permission mode the CLI is running in right now: `spec.mode` at spawn, then whatever the\n   *  last accepted `set_permission_mode` or the CLI's own status frame set. `spec.mode` stays the launch mode on purpose, since\n   *  the CLI takes a live switch to bypassPermissions only from a process launched in it. */\n  liveMode: string;\n  args: string[];\n  cwd: string;\n  busy: boolean;\n  /** A turn has taken this process and has not marked it `busy` yet: the spawn's own waits (the\n   *  initialize reply, up to 15 s) come first. The spawn cap skips it meanwhile. Without this a\n   *  second session starting in that gap evicted the newborn as the longest-idle process, and its\n   *  turn ended as \"claude exited 143: no output\" (2026-11-10, eleven subagents started at once\n   *  against a cap of four). */\n  claimed = false;\n  lastUsed: number;\n  stderr: string;\n  stray: string;\n  sent: Set<string>;\n  relays: Map<string, RelayEvent>;\n  exitCode: number | undefined;\n  queue: LineQueue;\n  /** The stdout index of each line in `queue`, in order, for `used` once nextEvent takes it. */\n  queuedIndexes: number[] = [];\n  child: SubprocessHandle;\n  key?: string;\n  resuming?: boolean;\n  onIdleResult?(): void;\n  /** An interrupt was written and the CLI has not answered it yet. dsh ends the turn's generator\n   *  on a user Stop before that answer lands, so the answer reaches an idle process; a stopped\n   *  turn answers with an error, which the wake filter drops, but a stopped `/compact` answers\n   *  with a plain result that read as a finished background task and woke the session\n   *  (2026-10-29). The next `result` line clears this and wakes nobody. The CLI's interrupt answer\n   *  carries no id to match on, so if a result of Claude's own (a turn a background task woke)\n   *  lands in the few ms before it, that one is the one swallowed and the interrupt's answer wakes\n   *  in its place: a wake is never lost, only credited to the other result. */\n  interruptOwed: boolean = false;\n  /** How many lines the queue held when the interrupt went out. Everything queued after it and\n   *  up to the answer is the interrupted turn's tail (probed on 2.1.312: a status frame, a fresh\n   *  init frame and an `assistant` frame saying \"Compaction canceled.\"), which the next turn would\n   *  otherwise read as its own and draw. */\n  interruptMark?: number;\n  /** A `/compact` dsh asked for (`compactOnCli`) is running. It holds `busy` like a turn, but no\n   *  turn is reading: a line written to stdin now would start a turn of its own after it. */\n  compacting: boolean = false;\n  dshIds?: Set<string>;\n  dshNames?: Map<string, string>;\n  relayed?: Set<string>;\n  steerPending: boolean = false;\n  /** Typed steers Claude has not read yet, by dsh message id: written to stdin during a native\n   *  tool, or left in dsh's inbox during a dsh tool (`relayed`) or, carrying a file or image, until\n   *  the next tool result (`boundary`). Cleared at the park that absorbs\n   *  them, at the relay result that carries them, at the turn's end and on interrupt; the steer\n   *  card lists these. */\n  steers: Map<string, WaitingSteer> = new Map();\n  /** How many mid-turn messages (typed or not, and file steers waiting to park) the CLI still has to\n   *  take. Holding a steer for an edit lowers it; at zero nothing is left to park on. */\n  forwarded = 0;\n  parked: \"steer\" | undefined = undefined;\n  /** The CLI's `dsh` MCP session belongs to a dsh that is gone (adopted after a restart) and the\n   *  reconnect after adoption gave up, because dsh had no live agent for the session yet. The next\n   *  turn, which implies one, asks once more before its prompt goes out. */\n  bridgeStale: boolean = false;\n  /** Set by the idle watchdog when it kills the process. */\n  idleKilled: boolean = false;\n  /** The silence it was allowed before that kill: longer while a tool call is out. */\n  idleKilledAfterMs?: number;\n  /** MCP servers this process has been told to ask about, by name. The CLI holds the override in\n   *  its own tool-permission context and offers no read-back, so the only record is the one kept\n   *  where the override was sent from. It hangs off the process for the same reason the override\n   *  does: both end when the process does, so nothing has to remember to clear it. */\n  mcpAsking: Set<string> = new Set();\n  staleResults: number = 0;\n  /** When this turn's prompt was written, for time-to-first-token; 0 once a result has read it. */\n  promptSentAt: number = 0;\n  /** `total_cost_usd` and `duration_api_ms` as of the last result frame. Both are running totals\n   *  for the life of the process, not this turn's figures, so each turn's own is the difference\n   *  from here. They hang off the process because a Translator lives for one turn and the CLI's\n   *  totals restart with the process. */\n  costSoFar: number = 0;\n  apiMsSoFar: number = 0;\n  /** This handle was attached to a CLI process that was already running and nothing recorded\n   *  where its totals stood, so its first result cannot be split into a turn's own share. */\n  totalsUnknown: boolean = false;\n  /** The model whose context window was last asked for, as `spec.model ?? \"\"`. A session started on\n   *  the mount's default model names no model at all, so \"asked\" cannot be read off the bank alone. */\n  windowAskedFor?: string;\n  prep?: TurnPrep;\n  /** A terminal wrote turns into this session's transcript since this process last spoke, so its\n   *  context is behind the file; the next prompt replaces it and resumes from the transcript. */\n  staleContext: boolean = false;\n  /** Sees every `control_response` line as it arrives, even between turns; true means consumed. */\n  controlListener?: (event: ClaudeEvent) => boolean;\n  /** The API-key line was drawn for this process. The init frame that carries `apiKeySource`\n   *  comes with every user message in -p mode, and each turn has a fresh translator, so the\n   *  once-per-process memory lives here. */\n  apiKeyNoted = false;\n  /** The CLI's guess at the next prompt, from a `prompt_suggestion` frame, kept until the next\n   *  prompt is written so the composer card can offer it between turns. Absent most of the time:\n   *  the CLI withholds one below two assistant messages, in plan mode, behind a pending\n   *  permission, on a rate-limit warning, with a cold prompt cache, or when its own quality\n   *  filter rejects the text. */\n  suggestion?: { text: string; at: number };\n  /** Fires when a suggestion arrives, so the adapter can push it to every open tab. */\n  onSuggestion?: () => void;\n  /** Fires for a `prompt_suggestion` frame the process did not keep, with the reason, so a\n   *  session that never shows a card can be read back from resume.log. */\n  onSuggestionDropped?: (reason: string) => void;\n  /** The session's name as the CLI last reported it in a `session_title_changed` frame: a name\n   *  someone set, never the CLI's own generated title. Set before `onTitle` fires; also the value\n   *  the adapter compares against before sending dsh's rename back, so an echo of a rename the\n   *  host itself sent costs no second write. */\n  title?: string;\n  /** Fires after `title` changes, so the adapter can rename dsh's session to match. */\n  onTitle?: (title: string) => void;\n  /** A result line passed since the last prompt went out. A suggestion is stored only then: the\n   *  CLI aborts its in-flight guess on new input, so a frame that still lands after a prompt was\n   *  written is for the turn before it. Set by the readline handler, cleared by the prompt write. */\n  resultSeen = false;\n\n  /** Spawn the child Claude and feed its stdout into the line queue, noting idle completion replies\n   *  so the adapter can open a dsh turn. */\n  constructor({\n    args,\n    cwd,\n    spec,\n    onExit,\n    command = \"claude\",\n    spawner = nodeSpawner,\n  }: {\n    args: string[];\n    cwd: string;\n    spec: ClaudeProcessSpec;\n    onExit?: ClaudeProcessOnExit;\n    command?: string;\n    spawner?: Spawner;\n  }) {\n    this.spec = spec;\n    this.liveMode = spec.mode;\n    this.args = args;\n    this.cwd = cwd;\n    this.busy = false;\n    this.lastUsed = Date.now();\n    this.stderr = \"\";\n    this.stray = \"\";\n    this.sent = new Set(); // steerKeys of messages already forwarded to Claude mid-turn (a typed steer's rpcId, a dsh message's id)\n    this.relays = new Map(); // relayed dsh tool call id → { resolve, reject, ... } awaiting dsh's result\n    this.exitCode = undefined;\n    this.queue = new LineQueue();\n    this.child = spawner(command, args, cwd);\n    this.child.stdin?.on(\"error\", () => {});\n    this.child.stderr?.on(\"data\", (d) => {\n      this.stderr = (this.stderr + d).slice(-2000);\n    });\n    const rl = createInterface({ input: this.child.stdout, crlfDelay: Infinity });\n    let lineIndex = 0;\n    rl.on(\"line\", (line) => {\n      const index = lineIndex++;\n      // The CLI's own mode changes (EnterPlanMode, an approved plan) reach the plugin only here;\n      // the bridge's plan-mode gate reads liveMode. The frame still queues as before.\n      const reported = statusMode(line);\n      if (reported !== undefined) this.liveMode = reported;\n      // Consumed here, not queued: the frame lands after the result that ended the turn, when no\n      // turn is reading, and a queued copy would open the next turn as an unknown event.\n      if (line.includes('\"prompt_suggestion\"') && this.noteSuggestion(line))\n        return this.used(index);\n      // Same reason: the frame lands at startup and after a rename, outside any turn.\n      if (line.includes('\"session_title_changed\"') && this.noteTitle(line)) return this.used(index);\n      // The CLI sends this snapshot right behind the answer to a re-sent `initialize` (an adoption),\n      // and the translator draws nothing for it. Queued, it woke idle sessions after every dsh\n      // restart, and the keeper replayed it on the next one, since no turn ever used it.\n      if (line.includes('\"background_tasks_changed\"') && isBackgroundTasksFrame(line))\n        return this.used(index);\n      // `\"type\":\"result\"` is how the CLI's JSON spells it